//
//  TarotPool.swift
//  UpNext — 타로 덱 40장 (웹 src/data/tarotPool.ts 1:1 포팅).
//  40장 × (이름 + 해설 4등급) × 4언어. id 0..39 불변 — 저장·웹 패리티가 이 번호에 묶인다.
//
//  ※ 자동 생성 (scripts/gen-ios-tarotpool.py). 수동 편집 금지 — 웹 원본 수정 후 재생성.
//
//  이름 = [ko, en, ja, zh]. readings = [great, good, fair, care] 순서,
//  각 원소 [ko, en, ja, zh]. name(_:lang:) / reading(_:tier:lang:) 으로 읽는다.
//

import Foundation

/// 타로 카드 한 장. icon 은 양 플랫폼 공존 PixelIcon 이름.
struct TarotCard: Hashable {
    /// 0..39 불변 — upnext_fortune.auraTarot 저장이 이 번호를 가리킨다
    let id: Int
    /// 이름 [ko, en, ja, zh]
    let name: [String]
    /// PixelIcon 이름
    let icon: String
    /// 등급별 해설 [great, good, fair, care], 각 원소 [ko, en, ja, zh]
    let readings: [[String]]
}

enum TarotPool {
    /// 덱 전체. 인덱스 == id.
    static let deck: [TarotCard] = [
        TarotCard(id: 0, name: ["등불", "The Lantern", "灯火", "提灯"], icon: "Lightbulb", readings: [
            ["등불이 비추는 자리가 오늘은 한결 넓어요. 앞이 흐리다는 이유로 아껴둔 큰 걸음이 있었을 거예요. 지금은 발밑 너머까지 어렴풋이 보이는 때예요. 신중하게 재는 얼굴 뒤로 이미 방향을 정해둔 당신이니, 불빛이 넓어진 김에 그 걸음을 옮겨 보세요.", "The lantern's circle of light is wider than usual today. There's probably a bigger step you've been saving because the way ahead looked hazy. Right now you can make out a little beyond your own feet. Behind that careful, measuring face you've already picked a direction, so while the light is generous, go ahead and take that step.", "灯火の照らす場所が、今日はひときわ広がっています。先が見えないからと、とっておいた大きな一歩があったはずです。いまは足もとの先まで、ほのかに見えてくる頃合い。慎重に見える顔の奥で、もう方角を決めているあなたですから、明かりの広いうちにその一歩を運んでみてください。", "提灯照亮的范围，今天格外宽。你大概有一步迟迟没迈，只因前路看不真切。此刻连脚下之外也隐约可见了。表面权衡再三，其实方向早在你心里定了，趁灯光正宽，把那一步迈出去吧。"],
            ["멀리는 여전히 어둑해도 다음 한 걸음만은 또렷하게 보여요. 요사이 전체 그림이 잡히지 않아 답답했다면, 오늘은 그 큰 그림 대신 발 앞의 밝은 자리 하나만 믿어도 돼요. 등불은 걸을 때마다 함께 움직이니, 보이는 그 한 걸음부터 디뎌 보세요.", "Farther out it's still dim, but the very next step shows clearly. If the big picture has refused to come together lately, today you can set it aside and trust the one bright patch in front of you. The lantern moves with you as you walk, so start with the step you can see.", "遠くはまだ暗くても、次の一歩だけははっきり見えています。このところ全体の絵が描けずもどかしかったなら、今日は大きな絵の代わりに、足もとの明るい場所だけを信じていいのです。灯火は歩くたびに一緒に動きますから、見えているその一歩から踏み出してみて。", "远处依然昏暗，但下一步看得分明。这阵子若因抓不住全貌而闷闷不乐，今天不必看大图，只信脚前那一小片亮就好。提灯会随着脚步一起移动，先踩上看得见的那一步。"],
            ["오늘은 불을 키우는 날이 아니라 꺼뜨리지 않는 날이에요. 눈에 띄는 진전이 없어 보여도, 지금 밝혀둔 자리가 있다는 것 자체가 요 며칠의 당신이 지켜온 거예요. 심지를 다듬듯 하던 일을 가만히 매만지며, 지금 빛이 닿는 자리를 한 번 둘러보세요.", "Today isn't for turning the light up. It's for keeping it from going out. Even if nothing visible has moved, the fact that there's a lit spot at all is something you've been protecting these past few days. Tend what you're doing the way you'd trim a wick, and take a look around at where the light already reaches.", "今日は火を大きくする日ではなく、消さない日です。目に見える前進がなくても、灯した場所があること自体が、ここ数日のあなたが守ってきたもの。芯を整えるように手もとの仕事を静かに撫でながら、いま光の届く場所を見回してみてください。", "今天不是把灯挑亮的日子，而是别让它熄灭的日子。看似没有进展，可此刻还留着一处亮着的地方，这本身就是你这些天守下来的。像修剪灯芯那样，把手头的事轻轻拢一拢，再看看光落到的地方。"],
            ["멀리까지 비추려고 심지를 무리하게 돋우면 등불은 오히려 흔들려요. 요즘 앞일을 한꺼번에 내다보려다 마음이 어두워졌다면, 오늘은 발 앞 한 뼘만 보아도 충분해요. 걸음을 늦추는 건 뒤처지는 게 아니라 불을 지키는 일이니, 그 속도는 당신이 정하면 돼요.", "Force the wick too high to light the distance and the lantern only flickers. If trying to see everything ahead at once has darkened your mood lately, one small stretch in front of your feet is enough for today. Slowing down isn't falling behind. It's how you keep the flame, and the pace is yours to set.", "遠くまで照らそうと芯を無理に伸ばすと、灯火はかえって揺れてしまいます。この頃、先のことをいちどに見通そうとして心が暗くなっていたなら、今日は足もとのわずかな先だけ見えれば十分。歩みをゆるめるのは遅れることではなく、火を守ること。その速さはあなたが決めていいのです。", "为了照得更远而硬拨灯芯，灯反而会晃。若最近总想一眼看穿前路，心里越看越暗，那今天只看脚前一小块就足够了。放慢脚步不是落后，是护住灯火，节奏由你来定。"],
        ]),
        TarotCard(id: 1, name: ["종이비행기", "The Paper Plane", "紙飛行機", "纸飞机"], icon: "Send", readings: [
            ["바람이 등 뒤에서 불어오는 날이에요. 접은 채로 아직 날리지 못한 종이비행기 하나, 오늘이 그걸 꺼내기 좋은 때예요. 완벽하게 접혔는지 살피는 손보다 던지는 손목이 오늘은 더 믿을 만해요. 오래 품은 것일수록 멀리 날 준비가 되어 있어요.", "The wind is at your back today. That paper plane you folded long ago and never threw, this is a good day to bring it out. Today the wrist that throws deserves more trust than the hand that keeps checking the folds. The things you've carried longest are the ones most ready to fly far.", "風が背中から吹いてくる日です。折ったまま、まだ飛ばせずにいる紙飛行機がひとつあるなら、今日は取り出すのにいい頃合い。きれいに折れたか確かめる手より、投げる手首のほうが今日は頼りになります。長く抱えてきたものほど、遠くへ飛ぶ支度ができています。", "风从背后吹来的日子。那架折好却一直没飞出去的纸飞机，今天正适合拿出来。比起反复检查折得够不够完美的手，今天更值得信的是抛出去的手腕。攥得越久的东西，越是准备好了远行。"],
            ["크고 무거운 것 말고, 가볍게 날릴 만한 것 하나가 오늘 손에 잡혀요. 요 며칠 머릿속으로만 접었다 폈다 하던 일이 있다면, 그중 제일 가벼운 것부터 날려 보세요. 멀리 가지 않아도 괜찮아요. 손을 떠나는 감각을 되찾는 것만으로 다음 비행이 쉬워져요.", "Not the big heavy thing. Something light enough to toss comes into reach today. If you've been folding and unfolding an idea in your head these past few days, launch the lightest one first. It doesn't need to go far. Just getting back the feel of letting go makes the next flight easier.", "大きく重いものではなく、軽く飛ばせそうなものがひとつ、今日は手になじみます。ここ数日、頭の中で折ってはひらいてを繰り返していたことがあるなら、いちばん軽いものから飛ばしてみて。遠くまで行かなくても大丈夫。手を離れる感覚を取り戻すだけで、次の飛行がぐっと楽になります。", "不挑大的重的，今天有一件轻巧的正好上手。这几天若有事在脑子里折了又拆、拆了又折，就先把最轻的那只放飞。飞不远也没关系，找回脱手的感觉，下一次起飞就容易了。"],
            ["오늘은 날리기보다 접는 선을 다듬는 시간이에요. 아직 던지지 못했다고 준비가 늦은 건 아니고, 멈춘 듯 보이는 시간에도 안에서는 접는 각이 자리를 잡는 중이에요. 마음에 들 때까지 펴서 다시 접어도 되는 하루이니, 그 여유를 그대로 써 보세요.", "Today is for smoothing the creases, not for launching. Not having thrown yet doesn't mean you're behind, and even in time that looks stalled, the folds are settling into place. It's a day when you're allowed to open it up and fold it again until it feels right, so use that room.", "今日は飛ばすより、折り目を整える時間です。まだ投げていないからといって支度が遅れているわけではなく、止まって見える間にも、内側では折りの角がおさまりつつあります。気に入るまでひらいて折り直していい一日ですから、その余白をそのまま使ってみてください。", "今天不急着放飞，先把折痕修整齐。还没抛出去，不代表准备迟了。看似停着的时间里，折角正在悄悄归位。这是可以摊开重折、直到满意为止的一天，把这份从容用足。"],
            ["당장 던지고 싶은 조급함이 스칠 수 있어요. 하지만 종이비행기는 접힌 채로 있는 시간도 비행의 일부예요. 요즘 결과를 서두르다 마음이 먼저 지쳤다면, 오늘은 날리려는 손을 잠시 내려놓아도 돼요. 접어둔 것은 사라지지 않고, 바람은 다시 불어와요.", "An itch to just throw it may pass through you. But the time a paper plane spends folded is part of the flight too. If chasing results has worn you out lately, you can set the throwing hand down for today. What's folded doesn't disappear, and the wind comes back around.", "いますぐ投げたい気持ちがよぎるかもしれません。けれど紙飛行機は、折られたままの時間も飛行のうちです。この頃、結果を急いで心が先に疲れていたなら、今日は飛ばそうとする手をしばらく下ろしても大丈夫。折って置いたものは消えませんし、風はまた吹いてきます。", "想立刻抛出去的急躁也许会掠过心头。但纸飞机折着不动的时间，同样是飞行的一部分。若最近为了赶结果先累了心，今天可以先把要放飞的手放下。折好的东西不会消失，风还会再来。"],
        ]),
        TarotCard(id: 2, name: ["새잎", "The New Leaf", "新芽", "新叶"], icon: "Leaf", readings: [
            ["볕이 좋은 날이에요. 최근에 시작한 작은 일, 아직 여려서 남에게 보이기 망설여지던 그 새잎을 오늘은 바깥에 내놓아도 돼요. 여리다는 건 약하다는 뜻이 아니라 자라는 중이라는 뜻이니, 빛을 받을수록 초록은 짙어져요. 어디까지 자랄지는 당신이 지켜보면 돼요.", "The light is good today. That small thing you started recently, the one still so tender you hesitated to show anyone, can come outside now. Tender doesn't mean weak. It means growing, and the more light it gets, the deeper the green becomes. How far it grows is yours to watch.", "日ざしのいい日です。最近始めた小さなこと、まだ柔らかくて人に見せるのをためらっていたその新芽を、今日は外に出しても大丈夫。柔らかいのは弱いからではなく、育っている途中だから。光を浴びるほど緑は濃くなります。どこまで育つかは、あなたが見守っていけばいいのです。", "阳光正好的日子。最近刚开始的那件小事，嫩得让你不好意思示人的新叶，今天可以放到外面了。嫩不是弱，是正在长。晒到的光越多，绿意越深，能长到哪里，你慢慢看。"],
            ["새잎에게 오늘 필요한 건 대단한 것이 아니라 거르지 않는 물 한 번이에요. 요즘 시작한 일이 티가 나지 않아 시들해졌다면, 오늘 몫의 손길만 건네 보세요. 언뜻 보면 그대로인 듯해도 잎은 어제보다 조금 벌어져 있어요. 꾸준함은 재능보다 조용히 힘이 세요.", "What the new leaf needs today isn't anything grand, just the one watering you don't skip. If something you started lately has gone quiet because it shows so little, offer today's share of care and no more. It may look the same at a glance, but the leaf has opened a little more than yesterday. Steadiness is quietly stronger than talent.", "新芽に今日必要なのは、立派な何かではなく、欠かさないひと注ぎの水です。始めたことに手ごたえがなくて気持ちがしぼんでいたなら、今日のぶんの手入れだけ渡してみて。ぱっと見は同じようでも、葉は昨日より少しひらいています。続けることは、才能より静かに強いのです。", "新叶今天需要的不是什么大动作，是不落下的那一次浇水。若近来因为看不出起色而心生倦意，就只递上今天这一份照料。乍看没变，叶片其实比昨天又舒展了一点。持之以恒，比天赋更安静，也更有力。"],
            ["자라는 게 눈에 보이지 않는 날에도 뿌리는 움직여요. 요 며칠 진전이 없다고 느꼈다면, 그건 멈춘 게 아니라 보이지 않는 곳에서 자리를 잡는 중이라는 뜻일 수 있어요. 오늘은 잎을 재기보다 흙이 마르지 않았는지만 확인해 주세요. 나머지는 새잎이 알아서 해요.", "Even on days when nothing seems to grow, the roots are moving. If it's felt like no progress these past few days, that may not be a stop, just settling in where you can't see. Today, don't measure the leaf. Just check that the soil hasn't gone dry. The new leaf handles the rest.", "育ちが目に見えない日にも、根は動いています。ここ数日、進んでいないと感じたなら、それは止まったのではなく、見えないところで根を張っている最中なのかもしれません。今日は葉を測るより、土が乾いていないかだけ確かめて。あとは新芽が自分でやっていきます。", "看不见生长的日子，根也在动。这几天若觉得毫无进展，那未必是停了，可能只是在看不见的地方扎根。今天别量叶子，只看看土有没有干。剩下的，新叶自己会办。"],
            ["잎을 잡아당긴다고 빨리 자라지는 않아요. 최근 들어 스스로에게 왜 아직 이만큼이냐고 물었던 적이 있다면, 오늘은 그 질문을 내려놓는 날이에요. 여린 시기를 건너는 중일 뿐 잘못 자라는 게 아니니, 재촉 대신 볕 좋은 자리로 화분을 옮겨 주는 정도면 충분해요.", "Pulling on a leaf doesn't make it grow faster. If you've caught yourself asking why you're only this far along, today is the day to put that question down. You're passing through a tender season, not growing wrong, so instead of hurrying it, just move the pot somewhere sunnier. That's plenty.", "葉を引っぱっても、早く育つわけではありません。この頃、自分に向かって、なぜまだこれだけなのかと問いかけたことがあるなら、今日はその問いを下ろす日です。柔らかい時期を渡っている最中なだけで、育ち方を間違えているのではありませんから、急かす代わりに日当たりのいい場所へ鉢を動かすくらいで十分です。", "拽叶子不会让它长得更快。若最近问过自己为什么才长这么点，今天就把这个问题放下吧。你只是正走在幼嫩的季节里，不是长歪了。不必催促，把花盆挪到向阳的位置，就足够了。"],
        ]),
        TarotCard(id: 3, name: ["연필", "The Pencil", "鉛筆", "铅笔"], icon: "PenSquare", readings: [
            ["지우개 걱정 없이 크게 써도 되는 날이에요. 머릿속에만 맴돌고 아직 적지 못한 문장이 하나쯤 있지 않나요. 오늘은 그걸 백지에 시원하게 풀어놓아 보세요. 틀리면 고치면 된다는 마음이 서는 날이라, 획이 커질수록 생각도 넓어져요. 어떤 이야기가 될지는 쓰는 당신 손에 달려 있어요.", "Today you can write big without worrying about the eraser. Isn't there a sentence that's been circling your head, still unwritten? Let it out across the page in broad strokes. It's a day when fixing later comes easily, so the bigger the strokes, the wider the thinking. What story it becomes is in your writing hand.", "消しゴムの心配なく、大きく書いていい日です。頭の中を巡るだけで、まだ書き出していない文章がひとつくらいありませんか。今日はそれを白い紙にのびのびと広げてみて。間違えたら直せばいい、そう思える日ですから、線が大きくなるほど考えも広がります。どんな話になるかは、書くあなたの手に委ねられています。", "今天可以放开写，不必顾忌橡皮。心里是不是转着一句还没落到纸上的话。今天就让它痛快地铺在白纸上吧。写错了改就是，笔画越大，思路越宽。写成什么故事，全看执笔的你。"],
            ["첫 줄만 쓰면 다음 줄은 생각보다 순순히 따라와요. 요즘 백지 앞에서 오래 서성였다면, 잘 쓰려는 마음을 잠깐 내려두고 아무 문장이나 한 줄 그어 보세요. 미뤄온 것처럼 보여도 실은 쓸 말이 속에 고여 있던 참이에요. 오늘은 그 물꼬만 트면 돼요.", "Write the first line and the next follows more willingly than you'd think. If you've been hovering over blank paper lately, set aside writing well for a moment and put down any line at all. It may look like you've been stalling, but really the words have been pooling up inside. Today you only need to open the channel.", "最初の一行さえ書けば、次の行は思いのほか素直についてきます。この頃、白い紙の前で長く足踏みしていたなら、うまく書こうとする気持ちをいったん置いて、どんな文でもひと筋引いてみて。先延ばしに見えても、実は書きたいことが内側に溜まっていたところ。今日はその水路をひらくだけでいいのです。", "只要写下第一行，第二行会比想象中顺从地跟上来。若最近在白纸前徘徊了太久，就先放下想写好的心，随手划下一句。看似拖延，其实要说的话早在心里积满了。今天只需开个口子。"],
            ["쓰기 전에 연필을 깎는 시간도 쓰는 일의 일부예요. 오늘은 문장을 쏟아내기보다 무엇을 쓰고 싶었는지 심을 다듬는 날이에요. 진도가 없다고 조급해할 것 없이, 요 며칠 흩어져 있던 생각을 가지런히 모아 두세요. 깎아둔 연필은 내일의 첫 획을 훨씬 가볍게 만들어요.", "Sharpening the pencil before you write is part of the writing. Today is less about pouring out sentences and more about trimming down to what you wanted to say. No need to fret over progress. Just gather the thoughts that have been scattered these past few days. A sharpened pencil makes tomorrow's first stroke much lighter.", "書く前に鉛筆を削る時間も、書くことの一部です。今日は文章を注ぎ出すより、何を書きたかったのか、芯を整える日。進みがないと焦ることはなく、ここ数日散らばっていた考えを、そっと並べ直しておいてください。削っておいた鉛筆は、明日の最初のひと筆をずっと軽くしてくれます。", "动笔前削铅笔的时间，也是写作的一部分。今天与其倾泻句子，不如把想写什么这根笔芯磨一磨。不必为没有进度着急，把这几天散落的念头拢整齐。削好的铅笔，会让明天的第一笔轻快得多。"],
            ["꾹 눌러 쓰면 심이 부러지기 쉬워요. 요즘 무엇이든 진하게 남기려고 힘을 주다 손이 먼저 지치지는 않았나요. 오늘은 흐리게 스케치만 해도 되는 날이에요. 흐린 선은 지우기도 쉽고 고치기도 쉬우니, 힘을 빼는 것이 오히려 오래 쓰는 요령이에요.", "Press too hard and the lead snaps. Have your hands been tiring first lately, from trying to leave everything in bold? Today a faint sketch is enough. Light lines are easy to erase and easy to fix, so easing off the pressure is actually how you write for the long haul.", "強く押しつけて書くと、芯は折れやすくなります。この頃、何でも濃く残そうと力を込めて、手のほうが先に疲れていませんでしたか。今日は薄く下書きするだけでいい日です。薄い線は消すのも直すのも簡単ですから、力を抜くことこそ、長く書き続けるこつなのです。", "太用力写，笔芯容易断。最近是不是什么都想写得又重又深，手先累了。今天淡淡地打个草稿就好。浅浅的线好擦也好改，学会松劲，反而是写得长久的诀窍。"],
        ]),
        TarotCard(id: 4, name: ["모닥불", "The Campfire", "焚き火", "篝火"], icon: "Fire", readings: [
            ["장작을 더 얹어도 좋은 날이에요. 담담한 얼굴로 지내왔어도 속에는 지피고 싶던 열기가 있었을 텐데, 오늘은 그 마음을 크게 태워도 불이 넘치지 않아요. 활활 타는 불은 당신만 데우는 게 아니라 곁에 있는 사람까지 데우니, 열의를 숨기지 말고 꺼내 보세요.", "It's a day you can add another log. You've kept a calm face, but there's been a heat inside you've wanted to light, and today you can let it burn big without it spilling over. A fire in full blaze doesn't warm just you. It warms the people beside you, so bring your enthusiasm out where it shows.", "薪をもうひと束くべてもいい日です。淡々とした顔で過ごしてきても、内側には焚きつけたい熱があったはず。今日はその気持ちを大きく燃やしても、火はあふれません。よく燃える火はあなただけでなく、そばにいる人まで温めますから、熱意を隠さずに出してみてください。", "今天可以再添几块柴。就算一直神色如常，心里想点起的那团热大概早就有了。今天把它烧旺也不会溢出来。烧得旺的火不止暖你自己，还能暖到身边的人，别藏了，把热情拿出来吧。"],
            ["불씨가 아직 살아 있어요. 요 며칠 시들해졌다고 느낀 일도 재를 헤쳐 보면 붉은 기운이 남아 있어요. 크게 벌일 것 없이 부채질이면 돼요. 식기 전에 손을 대는 것과 식은 뒤에 다시 지피는 것은 품이 다르니, 오늘 그 차이를 당신 쪽으로 가져오세요.", "The embers are still alive. Even the thing that felt like it had gone cold these past few days still holds a red glow if you stir the ash. No need for anything big. A little fanning will do. Reaching in before it cools takes far less than relighting it after, so bring that difference over to your side today.", "火種はまだ生きています。ここ数日しぼんだと感じていたことも、灰をかき分ければ赤い気配が残っています。大ごとにしなくても、うちわであおぐだけで十分。冷める前に手を入れるのと、冷めてから焚き直すのとでは手間が違います。今日はその差を、あなたの側に引き寄せてください。", "火种还活着。这几天觉得凉下去的事，扒开灰烬看看，里面还留着红。不用大动干戈，扇扇风就行。趁热接手和凉透重燃，费的力气不一样，今天把这个差别攥到自己手里。"],
            ["오늘은 불길을 키우기보다 온기를 나눌 때예요. 화력이 세지 않아도 곁을 데우기에는 지금 정도면 모자라지 않아요. 내색 없이 지내도 속으로 추웠을 사람이 주변에 있을 수 있으니, 그 곁에 잠시 앉아 있는 것만으로 모닥불의 일은 다 한 셈이에요.", "Today is for sharing warmth, not building the blaze. The fire doesn't need to be fierce. What you have now is enough to warm the people near you. Someone around you may have been cold without showing it, so just sitting beside them for a while does everything a campfire is meant to do.", "今日は火を大きくするより、ぬくもりを分かち合うときです。火力が強くなくても、そばを温めるにはいまのままで足りています。顔には出さなくても、内心冷えていた人が近くにいるかもしれません。その隣にしばらく座っているだけで、焚き火の仕事は果たされたようなものです。", "今天不是把火烧大的时候，是分暖的时候。火力不猛也无妨，要暖到身边的人，现在这样刚刚好。周围也许有人看着没事，心里其实凉了一阵，在那样的人身旁坐一会儿，篝火的活儿就算干完了。"],
            ["오늘은 활활보다 잔불이 어울려요. 계속 태우기만 한 불은 재만 남기기 쉬우니, 태우는 쪽이 아니라 쬐는 쪽에 앉아 보세요. 요즘 열심의 온도를 유지하느라 정작 자신은 데우지 못했다면, 지금 필요한 건 장작이 아니라 불가에 앉는 시간이에요.", "Today calls for embers, not flames. A fire that only ever burns tends to leave nothing but ash, so sit on the warming side instead of the burning side. If keeping your enthusiasm at full heat has left you unwarmed yourself, what you need now isn't firewood. It's a seat by the fire.", "今日は勢いよく燃やすより、熾火が似合います。燃やし続けるだけの火は灰ばかり残しやすいので、燃やす側ではなく、あたる側に座ってみて。この頃、熱心さの温度を保つのに精いっぱいで、自分自身を温められていなかったなら、いま必要なのは薪ではなく、火のそばに座る時間です。", "今天适合余烬，不适合烈焰。一味燃烧的火，容易只剩灰。别坐在添柴的那边，坐到取暖的那边去。若最近为了维持热度反而没暖到自己，你需要的不是柴，是坐在火边的时间。"],
        ]),
        TarotCard(id: 5, name: ["밀물", "The Rising Tide", "満ち潮", "涨潮"], icon: "Reload", readings: [
            ["물이 들어오고 있어요. 요즘 뭔가 빠져나간 듯 허전했다면, 이제 차오르는 차례가 온 것뿐이에요. 물이 차면 바닥에 얹혀 있던 배도 떠오르는 법이니, 밀어두었던 계획을 다시 물가로 끌어와 보세요. 띄울지 말지는 당신 몫이지만, 지금 물때는 띄우는 쪽에 서 있어요.", "The water is coming in. If things have felt drained and hollow lately, it's simply your turn to fill back up. When the tide rises, even boats resting on the bottom lift off, so pull that shelved plan back to the water's edge. Whether to launch is your call, but today the tide is standing on the launching side.", "水が入ってきています。この頃、何かが抜けていくような心細さがあったなら、今度は満ちてくる番が来ただけのこと。水が満ちれば、底についていた舟も浮かぶもの。脇に寄せていた計画を、もう一度水際まで引いてきてみてください。浮かべるかどうかはあなた次第ですが、いまの潮は浮かべる側に立っています。", "水正在涨。若最近总觉得有什么流走了，心里空落落的，那只是轮到上涨的时候了。水满了，搁在滩上的船也会浮起来。把搁置的计划重新拖到水边吧。开不开船由你，但眼下的潮水，站在开船这一边。"],
            ["차오르는 흐름이 느껴지는 날이에요. 흐름이 좋을 때는 노를 세게 젓지 않아도 배가 나아가요. 요 며칠 억지로 밀어붙이던 일이 있다면 오늘은 방향만 잡고 물살에 얹어 보세요. 힘을 덜 들이고도 나아가는 감각, 그게 오늘 당신 몫으로 들어온 물이에요.", "You can feel the current rising today. When the flow is with you, the boat moves without hard rowing. If you've been forcing something along these past few days, today just set the direction and let it ride the water. Getting somewhere with less strain, that's the tide that came in with your name on it.", "満ちてくる流れを感じる日です。流れがいいときは、櫂を強く漕がなくても舟は進みます。ここ数日、無理に押していたことがあるなら、今日は向きだけ定めて流れに載せてみて。力を入れずに進む感覚、それが今日あなたのぶんとして入ってきた水です。", "能感到水在往上涨的日子。水势顺的时候，不用拼命划桨，船也往前走。这几天若有硬撑着推的事，今天只管把稳方向，把它放到水流上。少费力也能前进的感觉，就是今天涨到你名下的潮水。"],
            ["물때를 읽는 날이에요. 밀물과 썰물은 재촉한다고 빨라지지 않지만, 지켜보는 사람에게는 들어오는 순간이 보여요. 지금 잠잠해 보이는 건 물이 마른 게 아니라 도는 중일 수 있으니, 조급함 대신 물가에 앉아 흐름을 살펴 두세요. 때를 아는 눈이 오늘의 수확이에요.", "Today is for reading the tide. The water doesn't come in faster for being rushed, but the one who watches can see the moment it turns. What looks still right now may not be dry, just circling, so trade urgency for a seat at the water's edge. An eye for timing is today's catch.", "潮目を読む日です。満ち引きは急かしても早まりませんが、見守る人には入ってくる瞬間が見えます。いま静かに見えるのは水が涸れたのではなく、巡っている途中なのかもしれません。焦る代わりに水際に腰かけて、流れを眺めておいてください。潮どきを知る目が、今日の収穫です。", "读潮汛的日子。潮起潮落，催不快也拦不住，可守着看的人，能看见水进来的那一刻。眼下的平静未必是水枯了，也许只是在回转。别急，坐在水边把流向看清楚。识得时机的眼力，是今天的收成。"],
            ["물이 빠진 자리에서만 주울 수 있는 것들이 있어요. 요즘 뭔가 줄어들고 빠져나가는 시기처럼 느껴졌다면, 오늘은 그 드러난 바닥을 살펴보는 날이에요. 잃은 것을 세는 대신 남은 것과 새로 보인 것을 주워 보세요. 물은 다시 들어오고, 그때의 당신은 빈손이 아닐 거예요.", "There are things you can only gather where the water has pulled back. If this has felt like a season of things receding, today is for looking at what the low tide reveals. Instead of counting what's gone, pick up what remains and what you can newly see. The water comes back in, and when it does, your hands won't be empty.", "水が引いた場所でしか拾えないものがあります。この頃、何かが減っていく時期のように感じていたなら、今日はあらわれた浜を見て歩く日です。失ったものを数える代わりに、残ったものと新しく見えたものを拾ってみて。水はまた入ってきますし、そのときのあなたは手ぶらではないはずです。", "有些东西，只有退潮后的滩涂上才捡得到。若最近像走在一段流失的日子里，今天就看看这片露出来的滩。别数丢了什么，捡捡剩下的和新看见的。水会再涨回来，那时的你不会空着手。"],
        ]),
        TarotCard(id: 6, name: ["실타래", "The Thread", "糸玉", "线团"], icon: "Link", readings: [
            ["매듭이 스르르 풀리는 날이에요. 어디서부터 손대야 할지 몰라 미뤄둔 엉킨 일이나 관계가 있다면, 오늘은 그 실타래에 손을 대도 좋아요. 겉보기엔 복잡해도 풀리기 시작하면 생각보다 한 가닥으로 이어져 있으니, 첫 매듭만 당신이 골라 주세요.", "The knots loosen easily today. If there's a tangled task or relationship you've put off because you didn't know where to begin, today you can touch that thread. It looks complicated, but once it starts giving, it turns out to run in one strand more than you'd think. You only have to choose the first knot.", "結び目がするりとほどける日です。どこから手をつければいいかわからず、後回しにしてきたもつれごとや間柄があるなら、今日はその糸玉に触れても大丈夫。見た目は込み入っていても、ほどけ始めれば案外ひと筋につながっています。最初の結び目だけ、あなたが選んでください。", "线结悄悄松开的日子。若有一团不知从哪儿下手的乱事或关系，今天可以伸手了。看着再乱，一旦解开了头，往往整团只是一根线。第一个结，由你来挑。"],
            ["실 끝 하나가 눈에 들어오는 날이에요. 엉킨 전체를 한 번에 풀 필요는 없고, 지금 보이는 그 끝을 살살 당기는 것으로 충분해요. 요 며칠 복잡하게만 느껴지던 일도 시작점 하나가 잡히면 결이 드러나요. 당기는 속도는 천천히, 방향은 당신이 잡으면 돼요.", "One end of the thread shows itself today. You don't have to untangle the whole thing at once. Gently pulling the end you can see is enough. Even something that has felt hopelessly knotted starts showing its grain once a starting point appears. Keep the pulling slow, and let the direction be yours.", "糸の端がひとつ、目に入る日です。もつれ全体をいちどにほどく必要はなく、いま見えているその端をそっと引くだけで十分。ここ数日、込み入って見えたことも、始まりがひとつつかめれば筋が見えてきます。引く速さはゆっくり、向きはあなたが決めればいいのです。", "有一个线头露出来的日子。不必一次解开整团，把眼前这个头轻轻一抽就够了。这几天只觉得千头万绪的事，抓到一个起点，纹理就会显出来。抽的速度慢一点，方向你来把。"],
            ["엉킨 실은 세게 당길수록 조여들어요. 오늘은 푸는 날이라기보다 엉킨 모양을 찬찬히 살피는 날이에요. 어디가 매듭이고 어디가 그저 겹친 것인지, 들여다보는 것만으로 절반은 푼 셈이에요. 제자리걸음 같아도 눈으로 풀어둔 길은 손이 기억하고 있어요.", "A tangled thread tightens the harder you pull. Today is less for untangling and more for studying the shape of the tangle. Which parts are true knots and which are only overlaps, just seeing that is half the work. It may feel like standing still, but the path your eyes untangle, your hands remember.", "もつれた糸は、強く引くほど締まってしまいます。今日はほどく日というより、もつれの形をじっくり眺める日。どこが結び目で、どこがただ重なっているだけなのか、見て取るだけで半分ほどいたようなものです。足踏みに見えても、目でほどいた道筋は手が覚えています。", "乱线越用力扯，缠得越紧。今天与其去解，不如仔细看看它缠成什么样。哪里是死结，哪里只是搭在一起，看清楚这一点，就等于解开了一半。像在原地踏步，可眼睛理顺过的路，手是记得的。"],
            ["오늘은 실타래를 내려놓을 차례예요. 풀리지 않는 것을 계속 쥐고 있으면 실보다 마음이 먼저 엉켜요. 요즘 그 일을 생각하는 시간이 길어졌다면, 잠시 손 닿지 않는 곳에 두어도 아무것도 잘못되지 않아요. 놓아둔 사이에 느슨해지는 매듭도 있는 법이에요.", "Today it's the thread's turn to be set down. Keep holding what won't come loose and your mind tangles before the thread does. If that problem has been taking up more and more of your thinking, leaving it out of reach for a while breaks nothing. Some knots loosen on their own while they're left alone.", "今日は糸玉を置く番です。ほどけないものを握り続けると、糸より先に心がもつれます。この頃、そのことを考える時間が長くなっていたなら、しばらく手の届かない場所に置いても、何も損なわれません。置いてある間にゆるむ結び目もあるのです。", "今天轮到把线团放下了。攥着解不开的东西不撒手，心会比线先缠住。若最近想这件事的时间越来越长，把它放到手够不着的地方，也不会出什么错。有些结，是在被搁下的日子里自己松的。"],
        ]),
        TarotCard(id: 7, name: ["편지", "The Letter", "手紙", "信"], icon: "Message", readings: [
            ["오늘은 긴 편지를 써도 좋아요. 미뤄둔 연락 하나, 전하지 못한 말 하나가 마음 한켠에 있지 않나요. 묵혀둔 만큼 길게 적어도 오늘은 부담스럽지 않게 닿는 날이에요. 늦게 도착하는 소식이라고 마음까지 상하는 건 아니니, 수신인은 당신이 이미 알고 있는 그 사람이에요.", "Today you can write the long letter. Isn't there one message you've put off, one thing you never quite said, sitting in a corner of your mind? However long it's been kept, today it lands without feeling heavy. News that arrives late doesn't arrive spoiled, and you already know who it's addressed to.", "今日は長い手紙を書いてもいい日です。先延ばしにした連絡、伝えられなかった言葉が、胸の隅にありませんか。寝かせたぶん長く綴っても、今日は重たくならずに届く日です。遅れて着く便りだからといって、気持ちまで傷むわけではありません。宛先は、あなたがもう知っているあの人です。", "今天可以写一封长信。是不是有一个搁下的联络、一句没能说出口的话搁在心头。攒了多久就写多长，今天寄出也不会显得突兀。迟到的消息不等于变了味的心意，收信人是谁，你其实早知道。"],
            ["짧은 안부부터 부치는 날이에요. 긴 사연은 나중으로 미뤄도, 잘 지내느냐는 한 줄은 오늘 보낼 수 있어요. 요 며칠 문득 떠오른 얼굴이 있었다면 그게 수신인이라는 신호일지 몰라요. 답장을 바라지 않고 보내는 안부가 오히려 제일 멀리 가요.", "Today is for sending the short hello first. The long story can wait, but asking how someone's been fits in one line and can go out today. If a face has drifted into your mind these past few days, that may be the address. The hello sent without expecting a reply travels farthest.", "短い挨拶から出す日です。長い事情はあとに回しても、元気ですかのひと言なら今日送れます。ここ数日、ふと浮かんだ顔があったなら、それが宛先の合図かもしれません。返事を求めずに送る便りが、かえっていちばん遠くまで届くのです。", "从一句短短的问候寄起。长话可以后放，问一句最近好吗，今天就能发出去。这几天若有一张脸忽然浮上来，那也许就是收信人的信号。不求回音的问候，反而寄得最远。"],
            ["오늘은 부치는 날이 아니라 받은 편지를 다시 읽는 날이에요. 지나간 말, 받아둔 마음 중에 제대로 헤아리지 못한 것이 있을 수 있어요. 무던히 넘긴 척했어도 마음에는 걸려 있던 문장을 오늘 한 번 더 읽어 보세요. 답은 그다음에 써도 늦지 않아요.", "Today isn't for mailing. It's for rereading what you've received. Among the words and kindnesses that came your way, there may be one you never fully took in. Read once more the line you pretended to shrug off but didn't. The reply can be written after that, and it won't be late.", "今日は出す日ではなく、もらった手紙を読み返す日です。過ぎた言葉、受け取ったままの気持ちの中に、汲みきれていないものがあるかもしれません。平気な顔で流したつもりでも、心に引っかかっていた文を、今日もう一度読んでみて。返事はそのあとで書いても遅くありません。", "今天不寄信，重读收到过的信。过去的话、收下的心意里，也许有没读透的。就算装作若无其事地翻了过去，心里挂着的那句，今天再读一遍。回信，之后再写也来得及。"],
            ["쓴 편지를 바로 부치지 않아도 돼요. 말이 마음보다 앞서 나가려 할 때는 하룻밤 서랍이 좋은 우체국이 돼요. 요즘 전하고 싶은 말이 급하게 차올랐다면, 오늘은 봉투를 닫기 전에 한 번만 재워 두세요. 하루 묵은 말은 대체로 더 순해져 있어요.", "You don't have to send the letter the moment it's written. When words try to outrun the heart, a drawer overnight makes a fine post office. If something you want to say has been rising fast lately, let it rest once before sealing the envelope. Words kept a day usually come out gentler.", "書いた手紙を、すぐに出さなくてもいいのです。言葉が気持ちより先に走り出しそうなときは、ひと晩の引き出しがいい郵便局になります。この頃、伝えたいことが急にせり上がってきたなら、封をする前にひと晩だけ寝かせてみて。ひと晩置いた言葉は、たいてい角が取れてやわらいでいます。", "写好的信不必立刻寄出。当话赶在心意前头，先在抽屉里放一夜，抽屉就是很好的邮局。若最近想说的话涨得很急，今天封口之前，先让它睡一晚。搁过一夜的话，大多温顺了不少。"],
        ]),
        TarotCard(id: 8, name: ["오래된 시계", "The Old Clock", "古い時計", "老时钟"], icon: "Clock", readings: [
            ["때가 무르익었어요. 남보다 늦었다는 생각에 덮어둔 일이 있다면, 오늘은 그 태엽을 감아도 좋아요. 오래된 시계는 빠르지도 늦지도 않게 제 속도로 가면서도 결국 맞는 시간에 닿아요. 늦은 게 아니라 당신의 시간에 맞춰 온 것이니, 이제 바늘을 움직여 보세요.", "The time is ripe. If there's something you shelved because you felt behind everyone else, today you can wind that spring. An old clock runs at its own pace, neither fast nor slow, and still arrives at the right time. You weren't late. You were keeping your own time, so go ahead and move the hands.", "頃合いが熟しました。人より遅れたと思ってしまい込んだことがあるなら、今日はそのぜんまいを巻いてもいい日です。古い時計は速くも遅くもなく自分の歩みで進みながら、それでも合うべき時刻にたどり着きます。遅れたのではなく、あなたの時間に合わせて来ただけ。さあ、針を動かしてみてください。", "时候到了。若有一件因为觉得比别人晚而收起来的事，今天可以给它上发条了。老钟走得不快也不慢，按自己的速度，最后总能对上该到的时刻。你不是迟了，是按你的时间到的，现在，让指针动起来吧。"],
            ["오늘의 걸음은 초침을 닮았어요. 크게 한 바퀴를 도는 그림보다, 작게 자주 똑딱이는 쪽이 오늘의 리듬에 맞아요. 요즘 멀리 있는 목표만 보다 지쳤다면, 눈금 하나만큼만 가 보세요. 초침이 쉬지 않고 돌기에 시침도 결국 옮겨 간다는 걸 당신은 이미 알고 있어요.", "Today's steps take after the second hand. Small, frequent ticks suit today's rhythm better than one grand sweep. If staring at the far-off goal has been wearing you down, move just one mark. You already know the hour hand only travels because the second hand keeps ticking.", "今日の歩みは秒針に似ています。大きくひと回りする絵図より、小さく刻んで進むほうが今日のリズムに合っています。この頃、遠くの目標ばかり見て疲れていたなら、目盛りひとつぶんだけ進んでみて。秒針が休まず回るから時針も動いていくことを、あなたはもう知っています。", "今天的步子像秒针。比起一大圈的宏图，小步频走的滴答更合今天的节奏。若最近盯着远处的目标盯累了，就只走一格。秒针不停，时针才终究会挪动，这个道理你早就懂。"],
            ["시계를 자꾸 들여다보지 않는 날이에요. 확인한다고 시간이 빨라지지 않듯, 재본다고 일이 앞당겨지지도 않아요. 걸음이 더디게 느껴져도 태엽은 감긴 만큼 돌고 있는 중이에요. 오늘은 흐름에 맡기고, 똑딱이는 소리를 배경 삼아 하던 일을 이어 가세요.", "A day for not checking the clock so often. Looking doesn't make time go faster, and measuring doesn't move the work up. Even if your pace feels slow, the spring is turning exactly as far as it was wound. Today, let it run, and keep at what you're doing with the ticking for company.", "時計を何度ものぞき込まない日です。確かめても時間が速まらないように、測っても物事は前倒しになりません。歩みが鈍く感じられても、ぜんまいは巻いたぶんだけ回っている最中です。今日は流れに任せて、時を刻む音を背に、手もとのことを続けてください。", "今天别老盯着钟看。看得再勤，时间不会变快，量得再多，事情也不会提前。脚步再慢，发条上了多少，就在转多少。今天交给节奏，把滴答声当背景，接着做手里的事。"],
            ["오늘은 태엽을 되감을 차례예요. 빨리 가려는 마음으로 태엽을 끝까지 감으면 오히려 무리가 가요. 요즘 마음의 초침이 실제보다 빨리 돌고 있었다면, 오늘은 일부러 한 박자 늦게 걸어 보세요. 시간에 쫓기는 대신 시간을 차고 다니는 쪽으로, 그 전환은 당신이 할 수 있어요.", "Today it's time to let the spring back down. Wind it to the end in a hurry to go faster and the works strain. If your inner second hand has been running ahead of the real one lately, walk a beat behind on purpose today. From being chased by time to wearing it on your wrist, that switch is yours to make.", "今日はぜんまいをゆるめる番です。急ごうとぜんまいを目いっぱい巻くと、かえって無理がかかります。この頃、心の秒針が実際より速く回っていたなら、今日はわざとひと呼吸遅く歩いてみて。時間に追われるのではなく、時間を身につけて歩く側へ。その切り替えは、あなたにできます。", "今天该让发条松一松了。想走快些就把发条上到底，反而伤了机芯。若最近心里的秒针转得比实际快，今天就故意慢半拍走。别被时间追着跑，改成把时间戴在手上，这个转身，你做得到。"],
        ]),
        TarotCard(id: 9, name: ["필름 카메라", "The Film Camera", "フィルムカメラ", "胶片相机"], icon: "Camera", readings: [
            ["필름이 넉넉한 날이에요. 좋은 장면 앞에서 아껴둘 이유가 없으니 셔터를 망설이지 마세요. 요 며칠 그냥 흘려보낸 순간이 아쉬웠다면, 오늘은 담고 싶은 것을 마음껏 담아도 돼요. 지나가면 다시 없는 장면들, 그걸 알아보는 눈은 이미 당신에게 있어요.", "There's plenty of film today. No reason to ration in front of a good scene, so don't hesitate at the shutter. If you've regretted letting moments slip by these past few days, today you can capture as much as you want. Scenes that never come around again, and the eye that spots them, you already have.", "フィルムがたっぷりある日です。いい場面を前に出し惜しむ理由はありませんから、シャッターをためらわないで。ここ数日、そのまま流してしまった瞬間が惜しかったなら、今日は収めたいものを思う存分収めて大丈夫。過ぎれば戻らない場面たち、それを見分ける目は、もうあなたに備わっています。", "胶卷充裕的日子。好景当前，不必省着快门。若这几天为白白流走的瞬间惋惜过，今天想拍什么就拍什么。过去了就不再来的画面，认得出它们的眼睛，你本来就有。"],
            ["좋은 장면은 지금 지나가는 중이에요. 나중에 더 좋은 구도가 나오리라 미루다 보면 필름은 그대로인데 빛이 바뀌어요. 완벽한 순간을 기다리기보다 지금 눈에 들어온 장면을 먼저 담아 보세요. 조금 흔들린 사진에도 그날의 공기는 고스란히 남아 있어요.", "The good scene is passing right now. Wait for a better composition later and the film stays the same while the light changes. Rather than holding out for the perfect moment, catch the one in front of you first. Even a slightly blurred photo keeps the whole air of the day.", "いい場面は、いままさに通り過ぎていくところです。あとでもっといい構図が来ると先送りするうち、フィルムはそのままでも光が変わってしまいます。完璧な瞬間を待つより、いま目に入った場面から先に収めてみて。少しぶれた写真にも、その日の空気はそのまま残ります。", "好画面正在经过。想着以后会有更好的构图，一拖再拖，胶卷还是那卷，光线却变了。与其等一个完美瞬间，不如先把眼前这幕收进来。稍微晃动的照片里，那天的空气也原样留着。"],
            ["초점을 맞추는 날이에요. 셔터를 누르기 전에 무엇을 담고 싶은지 파인더 안을 정리하는 시간도 촬영의 일부예요. 며칠째 눈앞에 걸리는 게 많아 흐릿했다면, 오늘은 구도만 잡아 두세요. 잘 맞춰둔 초점은 다음 셔터를 훨씬 수월하게 만들어 줘요.", "A day for focusing. Sorting out what you want in the frame before pressing the shutter is part of the shoot. If too much has been crowding your view and blurring things lately, just set the composition today. Focus set well in advance makes the next shutter far easier.", "ピントを合わせる日です。シャッターを切る前に、何を収めたいのかファインダーの中を整える時間も撮影のうち。ここ数日、目の前にかかるものが多くてかすんでいたなら、今日は構図だけ決めておいて。よく合わせたピントは、次のシャッターをずっと楽にしてくれます。", "对焦的日子。按下快门之前，把取景框里想留住的东西理清楚，这也是拍摄的一部分。若这几天眼前的杂事太多而模糊，今天只把构图定好。焦点对准了，下一次快门会顺手得多。"],
            ["오늘은 찍는 손을 내리고 맨눈으로 보는 게 좋아요. 담으려는 마음이 앞서면 정작 그 순간을 놓치기도 해요. 요즘 기록하고 증명하느라 피곤했다면, 오늘은 남기지 않아도 되는 시간을 자신에게 선물해 보세요. 눈으로만 본 장면도 마음속 앨범에는 오래 꽂혀 있어요.", "Today, lower the camera and look with bare eyes. When the urge to capture leads, you can miss the moment itself. If recording and proving have been tiring you out, gift yourself some time that doesn't need saving. A scene seen only with your eyes still stays long in the album inside.", "今日は撮る手を下ろして、素の目で眺めるのがよさそうです。収めようという気持ちが先に立つと、かえってその瞬間を逃すこともあります。この頃、記録することや証すことに疲れていたなら、今日は残さなくていい時間を自分に贈ってみて。目でだけ見た場面も、心のアルバムには長く挟まっています。", "今天放下拍的手，用肉眼看就好。想留住的心太急，反而会错过那个瞬间本身。若最近为了记录和证明而疲惫，今天送自己一段不必留痕的时间。只用眼睛看过的画面，也会在心里的相册里夹得很久。"],
        ]),
        TarotCard(id: 10, name: ["사진 한 장", "The Photograph", "一枚の写真", "旧照片"], icon: "Image", readings: [
            ["좋았던 시절의 나를 지금 불러와도 돼요. 최근 들어 문득 떠오르던 옛 장면이 있었다면 그건 우연이 아니라 연료일 수 있어요. 그때의 당신이 해냈던 걸 지금의 당신이 못 할 이유는 없으니, 서랍 속 사진을 꺼내듯 그 기억을 오늘의 힘으로 크게 써 보세요.", "You're allowed to call up the you from the good days. If an old scene has been surfacing lately, that may be fuel rather than accident. There's no reason today's you can't do what that you once did, so take the memory out like a photo from a drawer and spend it as strength, generously.", "いい頃の自分を、いま呼び戻しても大丈夫です。最近ふと浮かんでいた昔の場面があるなら、それは偶然ではなく燃料かもしれません。あのときのあなたにできたことを、いまのあなたにできない理由はありませんから、引き出しの写真を取り出すように、その記憶を今日の力として思いきり使ってみてください。", "可以把状态最好的那个自己请回来。若最近总有旧日的画面忽然浮现，那未必是偶然，可能是燃料。当年的你做到过的，如今的你没有理由做不到。像从抽屉里抽出照片那样，把那段记忆当成今天的力气，放开来用。"],
            ["그때 통했던 방식 하나를 오늘 다시 써 보는 날이에요. 잘 풀리던 시절의 당신에게는 분명 자기만의 요령이 있었어요. 새로운 방법을 찾느라 헤매는 대신, 이미 검증된 옛 방식 하나를 지금 일에 대 보세요. 사진 속 장면은 지나갔어도 그 손은 아직 당신 것이에요.", "Today, try one method that worked back then. The you from the smoother seasons had a knack all your own. Instead of wandering after a new approach, hold one proven old way up against the current task. The scene in the photo has passed, but the hands are still yours.", "あのころ通じたやり方をひとつ、今日また使ってみる日です。うまく回っていたころのあなたには、確かに自分なりのこつがありました。新しい方法を探してさまよう代わりに、すでに確かめ済みの昔のやり方を、いまのことに当ててみて。写真の中の場面は過ぎても、その手はまだあなたのものです。", "把当年管用的法子，今天再用一次。顺风顺水的那阵子，你分明有自己的一套。与其为找新方法兜圈子，不如把验证过的旧办法往眼下的事上一搭。照片里的场景过去了，那双手还是你的。"],
            ["앨범을 넘기듯 지나온 걸음을 훑어보세요. 어디까지 왔는지 확인하는 일은 뒤를 보는 게 아니라 방향을 다시 잡는 일이에요. 제자리 같다가도 넘겨 보면 장면이 꽤 바뀌어 있을 거예요. 오늘은 새 사진을 찍기보다 온 길을 한 장씩 확인해 두는 시간이에요.", "Leaf back through your steps like turning an album. Checking how far you've come isn't looking backward. It's resetting the heading. It may feel like standing still, yet turn the pages and the scenery has changed more than you thought. Today is for reviewing the road, not shooting new frames.", "アルバムをめくるように、歩いてきた道を眺めてみてください。どこまで来たか確かめるのは、後ろを向くことではなく、向きを取り直すことです。足踏みのようでいて、めくってみれば場面はずいぶん変わっているはず。今日は新しい写真を撮るより、来た道を一枚ずつ確かめておく時間です。", "像翻相册一样，把走过的路翻一遍。确认走到了哪里，不是回头，是重新校方向。感觉原地不动，翻着翻着会发现画面早换了好几张。今天不拍新照片，把来路一页页点清。"],
            ["빛바랜 것은 빛바랜 대로 두어도 괜찮아요. 그때가 좋았다는 마음이 지금을 흐리게 만들 필요는 없어요. 사진과 오늘을 나란히 놓고 비교하는 손을 잠시 내려 보세요. 그 시절이 빛나 보이는 건 지나서 보기 때문이고, 오늘도 언젠가는 꺼내 보는 한 장이 돼요.", "Faded things can be left faded. The feeling that those were the days doesn't need to dim this one. Set down the hand that keeps holding the photo next to today for comparison. That season shines because you're seeing it from afar, and today will one day be a photo you take out too.", "色あせたものは、色あせたままにしておいて大丈夫。あのころはよかったという気持ちが、いまを曇らせる必要はありません。写真と今日を並べて見比べる手を、しばらく下ろしてみて。あの時期が輝いて見えるのは過ぎてから眺めるからで、今日もいつか、取り出して眺める一枚になります。", "褪色的就让它褪色地放着吧。那时真好的念头，不必拿来把现在弄暗。把照片和今天并排比较的手，先放下来。那段日子显得亮，是因为隔着时间看。今天，也终会成为将来翻看的一张。"],
        ]),
        TarotCard(id: 11, name: ["펼친 책", "The Open Book", "開いた本", "摊开的书"], icon: "BookOpen", readings: [
            ["새 장이 펼쳐지는 참이에요. 지금 읽고 있는 장이 이야기의 전부가 아니라는 걸, 결말을 미리 단정하고 싶던 요즘의 마음에 오늘의 책장이 말해 줘요. 남은 페이지는 아직 두툼하고 다음 장은 생각보다 크게 넘어가요. 어떤 전개를 쓸지는 읽는 사람이자 쓰는 사람인 당신 몫이에요.", "A new chapter is opening. To the part of you that's wanted to call the ending early, today's page says the current chapter isn't the whole story. The remaining pages are still thick, and the next one turns more grandly than you'd expect. What happens next is yours, reader and writer both.", "新しい章がひらかれようとしています。いま読んでいる章が物語のすべてではないことを、結末を先に決めつけたくなっていた心に、今日のページが教えてくれます。残りのページはまだ分厚く、次の章は思ったより大きくめくれます。どんな展開を書くかは、読む人であり書く人でもある、あなたの領分です。", "新的一章正要展开。你现在读到的这章不是故事的全部，最近总想提前断定结局的心，今天的书页会亲口告诉它。剩下的页数还厚，下一页翻过去的动静比想的大。写什么样的展开，由又读又写的你说了算。"],
            ["한 페이지씩 읽어 나가는 날이에요. 남은 분량을 가늠하며 부담을 키우는 대신, 오늘 몫의 페이지만 넘기면 돼요. 이야기는 한꺼번에 읽히지 않아도 결국 이어지니, 지금 펼쳐진 곳부터 차근히 눈을 옮겨 보세요. 진도는 그렇게 조용히 쌓여요.", "A day for reading one page at a time. Instead of weighing the remaining pages and growing the burden, just turn today's share. A story doesn't have to be read in one sitting to hold together, so move your eyes from where it lies open. Progress piles up quietly like that.", "一ページずつ読み進める日です。残りの分量を見積もって荷を重くする代わりに、今日のぶんのページだけめくればいい。物語はいちどきに読めなくても、結局つながっていきますから、いまひらかれたところから、順に目を運んでみて。進みは、そうやって静かに積もります。", "一页一页读下去的日子。与其掂量剩余的厚度给自己加压，不如只翻今天这几页。故事不会一口气读完，但终究连得上。从摊开的地方起，慢慢移动目光。进度就是这样悄悄积起来的。"],
            ["같은 문장을 두 번 읽어도 좋아요. 빨리 넘어가는 것보다 지금 장을 제대로 읽는 게 오늘의 독서예요. 요 며칠 눈으로만 훑고 지나간 일이나 말이 있다면 오늘 한 번 곱씹어 보세요. 두 번째 읽기에서만 보이는 뜻이 있고, 그걸 줍는 건 천천히 읽는 사람이에요.", "It's fine to read the same sentence twice. Reading this chapter properly matters more today than getting through it. If there's something, or something someone said, that you only skimmed these past few days, chew it over once more. Some meanings appear only on the second read, and they go to the slow reader.", "同じ文を、もう一度読んでもいいのです。速くめくるより、いまの章をきちんと読むことが今日の読書。ここ数日、目でなぞるだけで通り過ぎたことや言葉があるなら、今日ひとつ噛みしめてみて。読み返してはじめて見える意味があり、それを拾えるのは、ゆっくり読む人です。", "同一句话读两遍也很好。比起赶进度，把当下这一章读透才是今天的阅读。这几天若有只扫了一眼就翻过去的事或话，今天嚼一嚼。有些意思只在第二遍里出现，捡到它的，是读得慢的人。"],
            ["책갈피를 꽂고 덮어둘 시간이에요. 결말이 궁금하다고 밤새 달리면 이야기도 읽는 사람도 지쳐요. 요즘 끝을 서둘러 확인하고 싶은 마음이 컸다면, 오늘은 여기까지 읽었다는 표시만 남겨 두세요. 덮어둔 책은 도망가지 않고, 내일의 당신이 이어 읽으면 돼요.", "Time to slip in the bookmark and close the cover. Race through the night for the ending and both the story and the reader wear out. If you've been anxious to know how it ends, just mark how far you've come today. A closed book doesn't run away. Tomorrow's you picks it up from there.", "しおりを挟んで、閉じておく時間です。結末が気になるからと夜通し走れば、物語も読む人も疲れてしまいます。この頃、終わりを急いで確かめたい気持ちが強かったなら、今日はここまで読んだという印だけ残しておいて。閉じた本は逃げません。明日のあなたが続きを読めばいいのです。", "该夹上书签合上书了。惦记结局连夜赶路，故事和读的人都会累。若最近特别想快点看到结尾，今天就只留一个读到这里的记号。合上的书不会逃走，明天的你接着读就是。"],
        ]),
        TarotCard(id: 12, name: ["돋보기", "The Magnifying Glass", "虫眼鏡", "放大镜"], icon: "Search", readings: [
            ["찾던 것이 생각보다 가까이에 있어요. 뭔가 놓치고 있다는 막연한 기분이 요즘 있었다면, 그 답은 먼 곳이 아니라 손 닿는 자리에 있을 가능성이 커요. 돋보기를 대듯 익숙한 곳을 크게 뒤져 보세요. 늘 지나치던 자리에서 걸려드는 것, 그걸 알아보는 눈은 당신 것이에요.", "What you've been looking for is closer than you thought. If a vague sense of missing something has followed you lately, the answer is likely within arm's reach, not far away. Search the familiar places thoroughly, as if holding a lens to them. Something catches in the spot you always pass by, and the eye that spots it is yours.", "探していたものは、思ったより近くにあります。何かを見落としているような気がしていたなら、その答えは遠い場所ではなく、手の届く場所にある見込みが高いのです。虫眼鏡をかざすように、なじみの場所をくまなく探ってみて。いつも素通りしていた場所で引っかかるもの、それを見分ける目はあなたのものです。", "找的东西比想象中近。若最近总有种漏掉了什么的模糊感觉，答案多半不在远处，就在手边。像举着放大镜那样，把熟悉的地方放大了翻一翻。在天天路过的位置上撞见的那个，认出它的眼睛是你的。"],
            ["한 곳만 정해 자세히 보는 날이에요. 여기저기 훑는 눈은 결국 아무것도 줍지 못하니, 오늘은 마음에 걸리는 지점 하나에만 돋보기를 대 보세요. 넓게 보던 때는 안 보이던 결이 가까이서는 드러나요. 들여다보는 시간만큼 또렷해지는 게 오늘의 법칙이에요.", "A day for choosing one place and looking closely. Eyes that sweep everywhere come up empty, so today hold the lens over the one spot that tugs at you. Up close, a grain appears that wide viewing keeps hidden. Things sharpen in proportion to the time you spend looking. That's today's rule.", "ひとところに決めて、じっくり見る日です。あちこちをなぞる目は、結局なにも拾えません。今日は気にかかる一点にだけ、虫眼鏡を当ててみて。広く見ていたときには見えなかった筋が、近くでは浮かび上がります。のぞき込んだ時間のぶんだけ、はっきりしてくるのが今日の決まりごとです。", "只定一处，仔细看的日子。到处扫的目光终究什么也拾不起，今天只把放大镜对准心里挂着的那一点。拉远时看不见的纹理，凑近了就会显形。看多久，就清楚多久，这是今天的法则。"],
            ["렌즈를 닦기 좋은 날이에요. 보이지 않는 게 대상 탓이 아니라 흐려진 렌즈 탓일 때도 있어요. 요즘 판단이 잘 서지 않았다면 오늘은 보는 눈 자체를 점검해 보세요. 피로한 눈, 앞선 짐작, 묵은 기준을 한 번 닦아내는 것으로 내일 보이는 것들이 달라져요.", "A good day for cleaning the lens. Sometimes what you can't see isn't the object's fault but the blur on the glass. If your judgment has felt cloudy lately, inspect the seeing itself today. Wipe off the tired eyes, the early guesses, the old standards, and tomorrow shows up differently.", "レンズを磨くのにいい日です。見えないのは相手のせいではなく、曇ったレンズのせいだったりもします。この頃、判断が定まらなかったなら、今日は見る目そのものを確かめてみて。疲れた目、先回りの思い込み、古びた物差しをひと拭きするだけで、明日見えるものが変わってきます。", "适合擦镜片的日子。看不清，有时不怪对象，怪镜片花了。若最近总拿不定判断，今天检查一下看东西的眼睛本身。疲惫的眼、先入的猜测、放旧的标准，擦过一遍，明天看见的就不一样了。"],
            ["너무 가까이 대면 오히려 흐려지기 마련이에요. 한동안 한 가지 일을 지나치게 들여다보느라 전체를 놓치고 있지는 않았나요. 오늘은 돋보기를 내려놓고 한 발 물러나 보는 날이에요. 거리를 두는 건 관심을 접는 게 아니라 초점을 되찾는 방법이에요.", "Hold it too close and everything blurs. Have you been staring so hard at one thing that the whole slipped out of view? Today is for setting the magnifier down and stepping back once. Distance isn't withdrawing interest. It's how the focus comes back.", "近づけすぎると、かえってぼやけてしまうものです。ひとつのことをのぞき込みすぎて、全体を見失ってはいませんでしたか。今日は虫眼鏡を置いて、一歩下がって眺める日です。距離を取るのは関心をたたむことではなく、ピントを取り戻すやり方なのです。", "凑得太近，反而模糊。是不是盯一件事盯得太久，把整体都盯丢了。今天把放大镜放下，退后一步。拉开距离不是收回关心，是找回焦点的办法。"],
        ]),
        TarotCard(id: 13, name: ["맑은 눈", "The Clear Eye", "澄んだ瞳", "澄澈的眼睛"], icon: "Eye", readings: [
            ["보는 눈이 밝은 날이에요. 겉으로는 무심해 보여도 당신은 생각보다 많은 걸 알아채는 사람이고, 오늘은 그 감각이 유난히 또렷해요. 요 며칠 마음에 걸리던 낌새가 있었다면 그 판단을 믿고 움직여도 좋아요. 알아챈 사람에게는 움직일 자격도 있어요.", "Your eye is bright today. You look indifferent on the outside, but you notice more than people guess, and today that sense runs especially sharp. If something has been nagging at your attention these past few days, you can trust that read and move on it. The one who noticed has earned the right to act.", "見る目が冴える日です。素っ気なく見えても、あなたは思いのほか多くのことに気づく人で、今日はその感覚がひときわ澄んでいます。ここ数日、心に引っかかっていた気配があったなら、その見立てを信じて動いても大丈夫。気づいた人には、動く資格もあるのです。", "眼力清亮的日子。看着不动声色，其实你比想象中察觉得多，今天这份感觉格外锐。这几天若有什么苗头让你放不下，可以信着那个判断动起来。察觉到的人，也有资格行动。"],
            ["오늘은 관찰을 행동 하나로 옮겨 볼 차례예요. 지켜보며 쌓아둔 것들이 이미 넉넉하니, 그중 하나를 골라 실행에 옮겨 보세요. 크지 않아도 괜찮아요. 눈으로 안 것을 손으로 확인하는 순간, 어림잡던 짐작은 확신 쪽으로 한 칸 옮겨 가요.", "Today, turn one observation into one action. You've gathered plenty just by watching, so pick one thing from the pile and try it. It doesn't need to be big. The moment your hands confirm what your eyes knew, a rough guess moves one notch toward certainty.", "今日は観察を、行動ひとつに移してみる番です。見守りながら溜めてきたものはもう十分ありますから、その中からひとつ選んで、実行に移してみて。大きくなくて構いません。目で知ったことを手で確かめた瞬間、あて推量だった見立ては、確信のほうへひと目盛り動きます。", "今天把观察换成一个动作。看着看着攒下的东西已经够多了，挑一件付诸实行吧。不用大。眼睛知道的事经手一验，模糊的猜测就朝着确信挪了一格。"],
            ["끼어들지 않고 지켜보는 날이에요. 모든 일에 손을 보태야 마음이 놓이는 사람일수록 오늘은 시선만 두는 연습이 필요해요. 판단을 붙이지 않고 그저 바라보면, 사람도 일도 스스로 제 모양을 드러내요. 지금은 보는 것만으로도 충분히 참여하고 있는 거예요.", "A day for watching without stepping in. The more you're someone who has to help before you can relax, the more today is practice in just resting your gaze. Look without attaching judgment and people and things show their own shape. Right now, watching is already taking part.", "口を挟まず、見守る日です。何にでも手を貸さないと落ち着かない人ほど、今日は視線だけを置く稽古が要ります。判断を添えずにただ眺めれば、人も物事も、自分から形をあらわしてくれます。いまは見ているだけでも、十分に関わっているのです。", "不插手，只看着的日子。越是事事都要搭把手才安心的人，今天越需要练习只把目光放上去。不加评判地看，人也好事也好，都会自己显出本来的样子。此刻光是看着，就已经在参与了。"],
            ["많이 본 눈에게는 쉬는 시간도 필요해요. 알아채는 사람은 그만큼 마음도 많이 쓰는 사람이라, 요즘 눈보다 마음이 먼저 피로했을 수 있어요. 오늘은 잠시 눈을 감는 날이에요. 모르는 척이 아니라 쉬는 것이니, 감은 사이 놓치는 것보다 회복되는 것이 더 많아요.", "Eyes that see a lot need their rest too. Noticing much means spending much heart, and lately the heart may have tired before the eyes did. Today is for closing them a while. It's not looking away. It's resting, and what recovers while they're closed outweighs what slips past.", "たくさん見てきた目には、休む時間も必要です。気づく人はそれだけ心も使う人ですから、この頃、目より心が先に疲れていたかもしれません。今日はしばらく目を閉じる日です。知らないふりではなく休むことですから、閉じている間に取りこぼすものより、回復するもののほうが多いのです。", "看得多的眼睛也需要休息。察觉得多的人，心也用得多，最近大概是心比眼先累了。今天暂且闭上眼。不是装作不知道，是休息。闭上眼的这段时间，恢复回来的比错过的多。"],
        ]),
        TarotCard(id: 14, name: ["우산", "The Umbrella", "傘", "雨伞"], icon: "Shield", readings: [
            ["우산이 넉넉한 날이에요. 오늘은 자기 몫의 비를 가리고도 곁에 있는 사람까지 씌워줄 여유가 있어요. 챙김을 받기만 하는 것도 주기만 하는 것도 아닌, 나란히 걷는 우산 속이 오늘의 그림이니 씌워주고 싶던 그 사람에게 먼저 다가가 보세요.", "The umbrella is roomy today. You can cover your own share of rain and still have room for the person beside you. Not only receiving care, not only giving it, but walking side by side under one umbrella, that's today's picture, so step first toward the one you've wanted to cover.", "傘にゆとりのある日です。今日は自分のぶんの雨をしのいだうえで、そばの人まで入れてあげる余裕があります。守られるだけでも、差しかけるだけでもない、並んで歩く傘の中が今日の絵ですから、入れてあげたかったあの人に、先に歩み寄ってみてください。", "伞面宽裕的日子。今天遮好自己那份雨之外，还有余裕把身边的人也拢进来。不是只被照顾，也不是只顾照顾，并肩走在一把伞下，才是今天的画面。想遮的那个人，先走近一步吧。"],
            ["챙길 것을 미리 챙기는 날이에요. 하늘이 흐려진 다음에 우산을 찾으면 늦으니, 오늘은 다가올 일에 필요한 것들을 미리 가방에 넣어 두세요. 거창한 대비가 아니어도 괜찮아요. 미리 챙긴 우산 하나가 그날 하루의 기분을 통째로 바꿔 놓기도 해요.", "A day for packing what you'll need before you need it. Look for the umbrella after the sky darkens and you're late, so tuck the day's necessities in your bag ahead of time. It doesn't have to be grand preparation. One umbrella packed early can turn a whole day's mood around.", "備えるものを、先に備える日です。空が曇ってから傘を探しては遅いので、今日はこれからのことに要るものを、先にかばんへ入れておいて。大げさな備えでなくて大丈夫。先に持った傘ひとつが、その日いちにちの気分を丸ごと変えてくれることもあります。", "把该备的先备好的日子。天阴了才找伞就晚了，今天把接下来用得上的东西先装进包里。不必兴师动众。提前备下的一把伞，有时能整个换掉那天的心情。"],
            ["오늘 할 일은 하늘을 한 번 올려다보는 거예요. 비가 올지 말지보다, 내 대비가 어디까지 되어 있는지 확인하는 게 먼저예요. 별일 없는 하루여도 챙겨둔 것을 점검하는 사람은 흐린 날에도 발걸음이 가벼워요. 우산이 어디 있는지만 확인해 두면 그걸로 족해요.", "Today's task is one look up at the sky. Before whether it will rain, check how far your preparations actually reach. Even on an uneventful day, the person who reviews what they've packed walks lighter under clouds. Just knowing where the umbrella is will do.", "今日やることは、空をひと目見上げることです。雨が降るかどうかより、自分の備えがどこまでできているかを確かめるのが先。何ごともない一日でも、備えたものを点検する人は、曇りの日も足取りが軽いのです。傘がどこにあるかだけ確かめておけば、それで足ります。", "今天要做的，是抬头看一眼天。会不会下雨在其次，先确认自己的准备到了哪一步。就算是无事的一天，清点过行装的人，阴天走路脚步也轻。确认一下伞放在哪儿，就够了。"],
            ["젖은 우산을 펴서 말릴 시간이에요. 누군가를 씌워주느라 정작 당신 어깨가 젖고 있었는지도 몰라요. 오늘은 지키는 역할을 잠시 내려놓고 자신을 말리는 시간을 가지세요. 잘 말린 우산이 다음 비에 더 든든한 것처럼, 쉬는 것도 지키는 일의 일부예요.", "Time to open the wet umbrella and let it dry. While you were covering someone, your own shoulder may have been getting soaked. Today, set the guardian role down a moment and dry yourself out. A well-dried umbrella holds up better in the next rain, and resting is part of protecting too.", "濡れた傘を、ひらいて乾かす時間です。誰かに差しかけるうちに、あなたの肩のほうが濡れていたのかもしれません。今日は守り役をしばらく下ろして、自分を乾かす時間を持ってください。よく乾いた傘が次の雨に頼もしいように、休むことも守ることの一部です。", "该把湿伞撑开晾一晾了。为别人撑伞的时候，你自己的肩膀也许一直在淋着。今天把守护的角色放一放，给自己一段晾干的时间。晾透的伞下场雨更牢靠，休息也是守护的一部分。"],
        ]),
        TarotCard(id: 15, name: ["자물쇠", "The Lock", "錠前", "锁"], icon: "Lock", readings: [
            ["맞는 열쇠가 이미 손안에 있어요. 열리지 않아 답답했던 일 하나가 있었다면, 오늘은 그 문 앞에 다시 서 볼 만해요. 그동안 돌려본 열쇠들이 헛수고가 아니라 맞는 것을 찾는 과정이었으니, 이번에는 잠긴 것에 손을 대도 좋아요. 여는 순간은 당신이 고르세요.", "The right key is already in your hand. If one door has stayed shut and frustrating, today is worth standing before it again. The keys you've tried weren't wasted effort. They were the sorting that finds the fit, so this time you can lay hands on what's locked. The moment of opening is yours to choose.", "合う鍵は、もう手の中にあります。ひらかなくてもどかしかったことがひとつあったなら、今日はその扉の前にもう一度立ってみる価値があります。これまで試してきた鍵は無駄ではなく、合うものを探す道のりでした。今日は閉ざされたものに手をかけても大丈夫。ひらく瞬間は、あなたが選んでください。", "对的钥匙已经在手里了。若有一件打不开而憋闷的事，今天值得再站到那扇门前。之前试过的那些钥匙不是白费，是找对钥匙的过程。这回可以对上锁孔了，开门的时刻，你来挑。"],
            ["열쇠 구멍을 살피듯 하나씩 맞춰 보는 날이에요. 한 번에 열리지 않는다고 문이 잘못된 건 아니에요. 방법을 바꿔가며 대 보는 그 손이 오늘 하루의 진도예요. 요즘 막혀 있다고 느낀 일이 있다면, 오늘은 거기에 다른 방향의 열쇠 하나를 꽂아 보세요.", "A day for trying keys one at a time, the way you'd study a keyhole. A door that doesn't open on the first turn isn't a broken door. The hand that keeps adjusting its approach is today's progress. If something has felt blocked lately, slide in one key from a different angle today.", "鍵穴をのぞくように、ひとつずつ合わせてみる日です。いちどでひらかないからといって、扉が悪いわけではありません。やり方を変えながら当ててみるその手が、今日いちにちの進みです。この頃ふさがっていると感じたことに、今日は別の向きの鍵をひとつ差してみてください。", "像端详锁孔那样，一把一把试的日子。一次没开，不代表门错了。换着法子试的那双手，就是今天的进度。若最近有觉得堵住的事，今天往里插一把不同方向的钥匙。"],
            ["잠긴 데는 잠긴 이유가 있어요. 오늘은 문을 여는 날이 아니라 문 앞에서 헤아리는 날이에요. 이 문이 왜 잠겨 있는지, 열면 무엇이 나올지 그려 보는 시간은 낭비가 아니에요. 진도가 없어 보여도 문 앞에 서 있는 사람만이 결국 여는 사람이 돼요.", "What's locked is locked for a reason. Today isn't for opening the door but for standing before it and wondering. Why it's shut, what might be behind it, imagining that isn't wasted time. It may look like no progress, but only the one standing at the door ends up the one who opens it.", "閉まっているものには、閉まっているだけの訳があります。今日は扉をひらく日ではなく、扉の前で推し量る日です。なぜ鍵がかかっているのか、ひらいたら何が出てくるのか、思い描く時間は無駄ではありません。進んでいないようでも、扉の前に立ち続けた人が、結局ひらく人になるのです。", "锁着，自有锁着的理由。今天不开门，在门前掂量。这扇门为什么锁着，打开会出来什么，想一想不算浪费。看似没有进展，但最后开门的，总是站在门前的人。"],
            ["억지로 따지 않는 날이에요. 무리해서 돌린 열쇠일수록 손에 무리가 가고, 문은 좀처럼 곁을 주지 않아요. 며칠째 열리지 않는 일 앞에서 힘이 들어가 있었다면, 오늘은 잠가둔 채 지키는 것도 답이라는 걸 떠올려 보세요. 어떤 문은 시간이 같이 열어 줘요.", "A day for not forcing it. The harder a key is turned, the more the hand strains, and the door gives nothing back. If your grip has been tightening for days over something that won't open, remember that keeping it locked and guarded is also an answer. Some doors are opened with time's help.", "無理にこじあけない日です。力任せに回した鍵ほど手を痛め、扉はなかなか心をひらいてくれません。ここ数日、ひらかないことを前に力が入っていたなら、今日は鍵をかけたまま守るのも答えだと思い出してみて。時間が一緒にひらいてくれる扉もあるのです。", "今天不硬撬。越使劲拧的钥匙越伤手，门也越不肯亲近。若这几天在打不开的事情面前一直较着劲，今天想想，先锁着守住，也是一种答案。有些门，是时间陪着一起开的。"],
        ]),
        TarotCard(id: 16, name: ["김 나는 잔", "The Steaming Cup", "湯気の立つカップ", "冒热气的杯子"], icon: "Coffee", readings: [
            ["잔을 두 손으로 쥐는 여유가 어울리는 날이에요. 제대로 쉰 게 언제였는지 가물가물했다면, 오늘은 쉼을 크게 허락받은 날이라고 생각해도 돼요. 따뜻한 것을 마시는 동안에는 아무것도 해결하지 않아도 되고, 그 시간이 오히려 다음 일들을 풀어 줘요.", "A day that suits holding the cup with both hands. If you can't quite remember your last real rest, consider today a generous permission slip for one. While you drink something warm you don't have to solve anything, and that time is what loosens everything that comes after.", "カップを両手で包むゆとりが似合う日です。ちゃんと休んだのがいつだったか思い出せないなら、今日は休むことをたっぷり許された日だと思って大丈夫。温かいものを飲んでいる間は、何も解決しなくていいのです。その時間がかえって、この先のあれこれをほどいてくれます。", "适合双手捧杯的日子。若连上次好好休息是什么时候都记不清了，就当今天获准大大方方地歇着。喝热饮的时间里什么都不用解决，而这段时间反倒会把接下来的事捋顺。"],
            ["한 모금 쉬고 다시 움직이면 돼요. 쉼은 멈춤이 아니라 순서의 일부예요. 계속 달리기만 한 사람보다 중간에 잔을 든 사람이 결국 더 멀리 가니, 오늘 일정 사이에 김이 오르는 시간을 한 칸 끼워 넣어 보세요. 그 한 칸이 오후를 바꿔요.", "One warm sip, then back to it. Rest isn't a stop. It's part of the sequence. The one who pauses for the cup ends up going farther than the one who only runs, so slot one steaming break into today's schedule. That one slot changes the afternoon.", "ひと口ぶん休んで、また動けばいいのです。休みは止まることではなく、順序のうち。走り続けた人より、途中でカップを手にした人のほうが結局遠くへ行きますから、今日の予定の合間に、湯気の立つ時間をひとますはさんでみて。そのひとますが、午後を変えます。", "喝一口，歇一下，再动身就好。休息不是停顿，是顺序的一部分。一路只顾跑的人，往往不如中途端起杯子的人走得远。今天在日程之间，嵌进一小段冒着热气的时间。那一小段，会改变整个下午。"],
            ["김이 오르는 동안 그냥 바라보는 날이에요. 식을까 봐 서둘러 마시는 대신, 잔에서 피어오르는 것을 가만히 지켜보는 여유가 오늘의 온도예요. 아무것도 안 하는 시간 같아도, 그 사이 마음은 가라앉을 것과 떠오를 것을 조용히 나눠 놓고 있어요.", "A day for just watching the steam rise. Instead of hurrying to drink before it cools, the room to sit and watch what lifts off the cup is today's temperature. It looks like doing nothing, but meanwhile the mind is quietly sorting what should settle and what should rise.", "湯気が立つ間、ただ眺める日です。冷めないうちにと急いで飲む代わりに、カップから立ちのぼるものを静かに見つめるゆとりが、今日の温度です。何もしていない時間のようでいて、その間に心は、沈むものと浮かぶものを静かに仕分けています。", "看着热气升起来就好的日子。别怕凉了急着喝，静静看杯口的热气打转，就是今天的温度。看似什么都没做，其间心里正把该沉的和该浮的悄悄分好。"],
            ["잔을 내려놓아도 괜찮아요. 따뜻한 한 잔마저 할 일처럼 느껴진다면 그건 몸이 먼저 보내는 신호예요. 오늘은 해야 할 일보다 몸의 소리를 위에 두세요. 눕고 싶으면 눕고 쉬고 싶으면 쉬는, 그 단순한 순서를 지키는 게 오늘의 성실이에요.", "It's okay to set the cup down. When even a warm drink starts to feel like a task, that's the body signaling first. Today, put its voice above the to-do list. Lie down if you want to lie down, rest if you want to rest. Keeping that simple order is today's diligence.", "カップを置いても大丈夫です。温かい一杯までやることのように感じるなら、それは体が先に送ってくれた合図。今日はやるべきことより、体の声を上に置いてください。横になりたければ横になり、休みたければ休む。その単純な順序を守ることが、今日の勤勉さです。", "把杯子放下也没关系。连一杯热饮都像任务的话，那是身体先发来的信号。今天把身体的声音排在待办之上。想躺就躺，想歇就歇，守住这个简单的顺序，就是今天的本分。"],
        ]),
        TarotCard(id: 17, name: ["붉은 마음", "The Red Heart", "紅い心", "滚烫的心"], icon: "Heart", readings: [
            ["마음이 시키는 쪽으로 가도 되는 날이에요. 덤덤한 척 지내왔어도 속에서는 크게 뛰는 것이 있었을 거예요. 오늘은 그 박동에 손을 들어줘도 돼요. 재고 따지는 일은 충분히 해 왔으니 이번에는 뛰는 쪽을 따라가 보세요. 어디로 향할지는 당신 마음이 이미 알고 있어요.", "Today you can go where the heart points. You've kept an even face, but something inside has been beating hard. Today you can side with that pulse. You've done plenty of weighing and measuring, so this time follow the part that leaps. Where it's headed, your heart already knows.", "心の向くほうへ進んでいい日です。平気な顔で過ごしてきても、内側では大きく脈打つものがあったはず。今日はその鼓動に軍配を上げて大丈夫。量ったり比べたりは十分やってきたのですから、今度は高鳴るほうについていってみて。どこへ向かうかは、あなたの心がもう知っています。", "可以顺着心走的日子。就算装得云淡风轻，心里大概早有什么在使劲跳。今天可以给那个心跳举手了。掂量和权衡做得够多了，这回跟着跳的那边走。去哪儿，你的心早就知道。"],
            ["좋아하는 것 하나에 솔직해져 보세요. 대단한 고백이 아니어도 돼요. 좋으면 좋다고 말하고, 하고 싶으면 하고 싶다고 적어 두는 것부터가 시작이에요. 그동안 마음을 뒷줄에 세워둔 채 지냈다면, 오늘은 그 순서를 한 칸만 앞으로 당겨 보세요.", "Be honest about one thing you love. It doesn't have to be a grand confession. Saying you like what you like, writing down what you want to do, that's the start. If your feelings have been standing at the back of the line, move them up one place today.", "好きなものひとつに、素直になってみてください。大それた告白でなくていいのです。いいと思ったらいいと言い、やりたければやりたいと書き留める。そこからが始まりです。これまで気持ちを後ろの列に並ばせてきたなら、今日はその順番を、ひとつだけ前へ繰り上げてみて。", "对喜欢的事坦率一次。不必是隆重的表白。喜欢就说喜欢，想做就写下想做，从这里开始就行。若一直让心排在队尾，今天把它的顺序往前挪一格。"],
            ["마음의 박자를 듣는 시간이에요. 빨리 뛰라고 재촉하지도 왜 이러냐고 다그치지도 말고, 지금 어떤 박자로 뛰는지만 들어 보세요. 감정은 재촉하면 숨고 들어주면 말을 걸어요. 겉과 속이 다르게 뛰는 날이라면, 그것도 그런 날이라고 적어 두면 돼요.", "Time to listen to the heart's tempo. Don't urge it faster, don't demand to know why it's like this. Just listen to how it's beating now. Feelings hide when rushed and speak when heard. If the outside and the inside are beating differently today, just note that it's that kind of day.", "心の拍子に耳を澄ます時間です。速く打てと急かすことも、どうしたのと問い詰めることもせず、いまどんな拍子で打っているかだけ聴いてみて。感情は急かせば隠れ、聴いてあげれば話しかけてきます。表と内で違う打ち方の日なら、そういう日だと書き留めておけばいいのです。", "听心跳节拍的时间。不催它快，也不怪它乱，只听它现在跳的什么拍子。情绪这东西，越催越躲，肯听就开口。今天若表和里跳得不一样，那就记一笔，今天是这样的日子。"],
            ["크게 뛴 마음일수록 쉬는 시간이 필요해요. 요즘 감정의 볼륨이 계속 높게 틀어져 있었다면, 오늘은 그 다이얼을 조금 낮추는 날이에요. 무뎌지는 게 아니라 고르게 만드는 것이니 걱정하지 않아도 돼요. 조용해진 마음에서만 들리는 소리가 있고, 그걸 들을 사람은 당신이에요.", "A heart that has raced needs its rest. If the volume on your feelings has been turned up high for a while, today is for easing the dial down. It's not going numb. It's evening out, so don't worry. Some sounds can only be heard in a quieted heart, and you're the one meant to hear them.", "大きく打った心ほど、休む時間が要ります。この頃、感情の音量が高いまま回り続けていたなら、今日はそのつまみを少し下げる日です。鈍くなるのではなく、ならすことですから心配いりません。静まった心にだけ聞こえる音があり、それを聴くのはあなたです。", "跳得猛的心，更需要休息。若最近情绪的音量一直开得很高，今天把旋钮调低一点。不是变钝，是调匀，不必担心。有些声音只在安静下来的心里响，听它的人，是你。"],
        ]),
        TarotCard(id: 18, name: ["두 그림자", "The Two Shadows", "二つの影", "两道影子"], icon: "Users", readings: [
            ["함께라서 더 커지는 날이에요. 혼자 짊어지고 오던 일이 있었다면, 오늘은 곁의 손을 잡고 판을 넓혀도 좋아요. 나란히 걷는 그림자는 혼자일 때보다 길어지니, 같이 하자는 말 한마디가 일의 크기를 바꿔요. 먼저 내미는 쪽이 오늘은 당신이어도 돼요.", "A day that grows larger for being shared. If you've been carrying something alone, today you can take the hand beside you and widen the field. Shadows walking side by side stretch longer than one alone, and a single suggestion to do it together changes the size of the work. Today, the one who reaches first can be you.", "一緒だから大きくなる日です。ひとりで背負って歩いてきたことがあるなら、今日はそばの手を取って、構えを広げても大丈夫。並んで歩く影はひとりのときより長く伸びます。一緒にやろうというひと言が、ことの大きさを変えるのです。先に差し出す側が、今日はあなたでもいいのです。", "因为同行而变大的日子。若有一直独自扛着的事，今天可以牵起身边的手，把摊子铺大一点。并肩走时影子比一个人长，一句一起吧，就能改变事情的尺寸。今天先伸手的，可以是你。"],
            ["보폭을 맞추자고 먼저 말해 봐도 좋아요. 상대가 알아주기를 기다리는 대신, 같이 걷고 싶다는 뜻을 먼저 꺼내는 게 오늘의 걸음이에요. 거창할 것 없이 밥 한 끼, 안부 한 줄이면 충분해요. 맞춰본 보폭은 다음에 만날 때 기억되어 있어요.", "It's fine to be the one who suggests matching pace. Rather than waiting to be noticed, saying you'd like to walk together is today's step. Nothing grand needed. A shared meal, one line of hello is plenty. A pace once matched is remembered at the next meeting.", "歩幅を合わせようと、先に言ってみてもいい日です。相手が察してくれるのを待つ代わりに、一緒に歩きたい気持ちを先に出すのが今日の一歩。大げさでなくていい、ごはんひとつ、挨拶ひと行で十分です。合わせてみた歩幅は、次に会うときも覚えられています。", "先开口提议对齐步子也很好。与其等对方察觉，不如先把想同行的意思递出去，这就是今天的一步。不用隆重，一顿饭，一行问候，足矣。对齐过的步幅，下次见面还记得。"],
            ["말없이 나란히 걷는 것만으로 채워지는 날이에요. 모든 동행에 대화가 필요한 건 아니고, 곁에 있다는 감각만으로 이어지는 시간도 있어요. 요즘 관계에 뭔가 더 해야 한다는 부담이 있었다면 오늘은 내려놓아도 돼요. 나란한 그림자면 오늘의 그림은 완성이에요.", "A day filled by walking side by side without words. Not every companionship needs conversation. Some hours hold together on the simple sense of someone near. If your relationships have felt like they demand something more lately, set that down today. Two shadows in parallel complete the picture.", "黙って並んで歩くだけで満ちてくる日です。すべての道行きに会話が要るわけではなく、そばにいる感覚だけでつながる時間もあります。この頃、関係に何か足さなければと重かったなら、今日は下ろして大丈夫。影が並んでいれば、今日の絵はできあがりです。", "不说话，肩并肩走着就被填满的日子。不是所有同行都需要对话，有些时间靠彼此在场就连得起来。若最近总觉得该为关系再做点什么，今天可以放下。影子并排，今天的画就完整了。"],
            ["잠시 각자의 속도로 걸어도 돼요. 맞추느라 애쓴 걸음은 티가 나지 않아도 꽤 힘이 들어요. 오늘 거리를 조금 두는 건 멀어지는 게 아니라 다시 나란히 걷기 위한 숨 고르기예요. 혼자 걷는 동안 당신의 원래 보폭을 되찾아 두세요. 그래야 다음 동행이 편해져요.", "It's fine to walk at your own pace for a while. Steps spent matching someone else's cost more than they show. A little distance today isn't drifting apart. It's catching your breath so you can walk in step again. While walking alone, recover your natural stride. The next walk together will be easier for it.", "しばらく、それぞれの速さで歩いても大丈夫。合わせようと励んだ歩みは、目立たなくてもかなりくたびれるものです。今日少し距離を置くのは離れることではなく、また並んで歩くための息継ぎです。ひとりで歩く間に、あなた本来の歩幅を取り戻しておいて。次の道行きが楽になります。", "暂时各走各的速度也可以。为了合拍而用的力，看不出来，却相当耗人。今天拉开一点距离不是疏远，是为了再度并肩的换气。独自走的时候，把你原本的步幅找回来。这样，下一段同行才轻松。"],
        ]),
        TarotCard(id: 19, name: ["거울", "The Mirror", "鏡", "镜子"], icon: "User", readings: [
            ["거울 속 내가 마음에 드는 날이에요. 남에게 보이는 나와 내가 아는 나 사이의 틈이 오늘은 유난히 좁아요. 요즘 자신을 의심하는 쪽으로 기울어 있었다면, 오늘 비친 모습을 근거로 삼아도 돼요. 그 확신을 들고 나가서 하려던 일을 당신 방식대로 해 보세요.", "A day when you like what's in the mirror. The gap between the you others see and the you that you know is unusually narrow today. If you've been leaning toward self-doubt lately, today's reflection can serve as evidence. Take that certainty out the door and do the thing you meant to do, your way.", "鏡の中の自分が、気に入る日です。人に見える自分と、自分が知っている自分との隙間が、今日はひときわ狭くなっています。この頃、自分を疑うほうへ傾いていたなら、今日映った姿を拠りどころにして大丈夫。その確信を持って出かけて、やろうとしていたことをあなたのやり方でやってみてください。", "对镜子里的自己看得顺眼的日子。给别人看的我和自己认识的我，今天缝隙格外小。若最近总往怀疑自己那边偏，今天照见的样子可以当作证据。带着这份确信出门，按你的方式，把想做的事做了。"],
            ["고치고 싶던 한 가지를 오늘 매만져 보세요. 전부 바꾸려면 엄두가 나지 않지만 하나라면 오늘 안에 돼요. 손보고 싶던 습관이든 말버릇이든 자세든, 거울 앞에서 하나만 고르세요. 매만진 그 한 곳이 거울을 볼 때마다 눈에 들어오며 다음 하나를 불러요.", "Touch up the one thing you've wanted to change. Changing everything is daunting, but one thing fits inside today. A habit, a way of speaking, a posture, choose just one at the mirror. That one tended spot catches your eye at every glance after, and calls up the next one.", "直したかったひとつを、今日手入れしてみてください。全部変えるのは気が重くても、ひとつなら今日じゅうにできます。整えたかった癖でも、言い回しでも、姿勢でも、鏡の前でひとつだけ選んで。手をかけたその場所が、鏡を見るたび目に入り、次のひとつを呼んでくれます。", "把想改的那一处，今天修一修。全部换掉没有底气，一处的话今天之内就行。想调整的习惯、口头禅或坐姿，在镜子前只挑一个。修过的那一处会在每次照镜子时跳进眼里，替你唤来下一处。"],
            ["비친 모습을 평가 없이 바라봐 주세요. 잘났는지 못났는지 점수를 매기는 눈을 잠시 끄고, 그냥 오늘의 나를 확인만 해 보는 거예요. 남들 앞에서는 무던해 보여도 자신에게는 박했던 요즘이라면 더욱 그래요. 판단을 걷어낸 거울에는 생각보다 괜찮은 사람이 서 있어요.", "Look at the reflection without grading it. Switch off the eye that keeps score, and simply confirm who's there today. All the more if you've been mild with everyone else and hard on yourself lately. In a mirror wiped clean of judgment stands someone more decent than you expected.", "映った姿を、値踏みせずに眺めてあげてください。良し悪しの点をつける目をしばらく消して、ただ今日の自分を確かめるだけでいいのです。人前では穏やかに見えても、自分には厳しかったこの頃なら、なおさらです。判断を取り払った鏡には、思ったよりちゃんとした人が立っています。", "不打分地看看镜中人。把评判好坏的眼睛暂时关掉，只确认一下今天的自己。要是近来在别人面前随和，对自己却苛刻，就更要这样。撤掉评判的镜子里，站着一个比想象中不错的人。"],
            ["오늘은 거울을 자꾸 보지 않는 편이 나아요. 들여다볼수록 흠이 늘어나는 날이 있고, 오늘이 그런 날일 수 있어요. 자기 검열의 거울은 잠시 벽 쪽으로 돌려 두세요. 나를 살피는 일과 나를 다그치는 일은 다르니, 살피는 것마저 잠시 쉬어 가는 쪽을 골라도 돼요.", "Today it's better not to check the mirror too often. There are days when every look adds a flaw, and this may be one. Turn the mirror of self-scrutiny to the wall for now. Examining yourself and berating yourself are different things, so today you're allowed to rest even from the examining.", "今日は鏡を何度も見ないほうがよさそうです。のぞき込むほどあらが増える日があって、今日がそうかもしれません。自分を検分する鏡は、しばらく壁のほうへ向けておいて。自分を見つめることと問い詰めることは別ですから、確かめることさえ、今日は休んでいいのです。", "今天少照镜子为好。有些日子越照瑕疵越多，今天可能正是。把自我审视的镜子暂且转向墙。照看自己和苛责自己是两回事，连照看也歇一歇，这个选择也是可以的。"],
        ]),
        TarotCard(id: 20, name: ["전지가위", "The Pruning Shears", "剪定ばさみ", "修枝剪"], icon: "Sword", readings: [
            ["정원사가 굵은 가지에 가위를 대는 건 나무를 믿기 때문이에요. 놓아야 하는 걸 알면서도 쥐고 있던 것이 하나쯤 있었을 거예요. 오늘은 잘라낸 자리로 빛이 드는 날이라, 큰 정리를 해도 나무는 오히려 무성해져요. 비워진 자리에 무엇을 자라게 할지 고르는 일은 당신에게 남아 있어요.", "A gardener sets shears to a thick branch out of trust in the tree. There's probably been something you knew to release and kept holding anyway. Today, light falls into the cleared space, so even a big pruning leaves the tree fuller, not barer. What to grow in the opened room is still yours to choose.", "庭師が太い枝にはさみを入れるのは、木を信じているからです。手放すべきだとわかっていながら握っていたものが、ひとつくらいあったはず。今日は切ったあとに光が差し込む日ですから、大きく整理しても木はかえって茂ります。空いた場所に何を育てるか、選ぶ楽しみはあなたに残っています。", "园丁敢把剪刀对准粗枝，是因为信得过这棵树。明知该放手却一直攥着的东西，你大概也有一件。今天剪过的位置会照进光，就算大动一场，树反而更繁茂。空出来的地方长什么，留给你来挑。"],
            ["가지치기는 굵은 가지가 아니라 마른 잔가지부터 시작하는 법이에요. 요즘 마음 한쪽에서 이건 아니다 싶었던 사소한 것이 하나쯤 짚일 거예요. 오늘은 그 잔가지 하나만 정리해도 나무의 숨이 트여요. 가위를 댈 자리는 이미 눈에 들어와 있을 거예요.", "Pruning starts with the dry twigs, not the thick limbs. Something small has probably been whispering at the edge of your mind that it no longer fits. Clearing just that one twig today lets the tree breathe. Where to set the shears, you've likely already seen.", "枝の手入れは、太い枝ではなく枯れた小枝から始めるものです。この頃、心のどこかでこれは違うと感じていた小さなことが、ひとつ思い当たるはず。今日はその小枝ひとつ整えるだけで、木の息がとおります。はさみを入れる場所は、もう目に入っているのではないでしょうか。", "修枝不从粗枝下手，先剪枯掉的细枝。最近心里大概闪过一丝这样不太对的感觉。今天只清理那一根细枝，树就能透气。剪刀该落在哪儿，其实早就映进你眼里了。"],
            ["가위를 들기 전에 정원사는 나무를 한 바퀴 돌며 살펴봐요. 멀리서 보면 다 비슷해도 안에서는 마른 가지와 자라는 가지가 나뉘고 있어요. 오늘은 자르는 날이 아니라 구분하는 날이에요. 어느 쪽이 살아 있는 가지인지 눈으로만 짚어두면 돼요.", "Before lifting the shears, a gardener circles the tree and looks. From a distance it all looks alike, but inside, dry branches and growing ones are sorting themselves out. Today is a day for telling them apart, not for cutting. Marking which branches are alive, by eye only, is enough.", "はさみを手にする前に、庭師は木のまわりをひと回りして眺めます。遠目には同じでも、内側では枯れる枝と伸びる枝が分かれつつあります。今日は切る日ではなく、見分ける日。どちらが生きている枝か、目で確かめておくだけでいいのです。", "举剪之前，园丁会先绕树走一圈。远看都差不多，树里面，枯枝和生枝正在分开。今天不是剪的日子，是分辨的日子。哪一边是活枝，用眼睛点一点就够了。"],
            ["가지치기에도 철이 있어서, 아무 때나 자르면 나무가 몸살을 해요. 정리해야 한다는 조급함이 요 며칠 마음을 재촉했을지 몰라요. 오늘은 가위를 내려놓고 나무를 그냥 두는 날이에요. 자를지 말지는 다음에 정해도 늦지 않아요.", "Pruning has its season too, and cutting out of season makes the tree ache. The urge to tidy everything may have been hurrying you these past few days. Today, set the shears down and let the tree be. Whether to cut can be decided another day, and it won't be late.", "枝の手入れにも季節があって、時を選ばず切ると木は弱ってしまいます。片づけなければという焦りが、ここ数日心を急かしていたかもしれません。今日ははさみを置いて、木をそのままにしておく日です。切るかどうかは、この次に決めても遅くありません。", "修枝也讲时节，不合时宜地剪，树会生一场病。必须收拾的急迫感，这几天也许一直催着你。今天把剪刀放下，让树就那么待着。剪不剪，下次再定也不迟。"],
        ]),
        TarotCard(id: 21, name: ["과녁", "The Target", "的", "箭靶"], icon: "Target", readings: [
            ["여러 과녁에 흩어지던 화살이 오늘은 한가운데로 모이는 날이에요. 벌여둔 것들 가운데 가장 원하는 과녁이 무엇인지, 속으로는 이미 알고 있죠. 겨눈 곳에 힘이 실리는 날이니 가장 큰 과녁을 향해 시위를 놓아도 좋아요. 어디를 겨눌지는 당신 손끝이 기억하고 있어요.", "Arrows that scattered across many targets gather toward one center today. Among everything you've spread out, you already know which target you want most. Strength lands where you aim today, so you may loose the string at the biggest one. Your fingertips remember where to point.", "あちこちに散っていた矢が、今日はまん中へ集まってくる日です。広げてきたことの中で、いちばん望んでいる的がどれか、内心ではもう知っているはず。狙った場所に力が乗る日ですから、いちばん大きな的に向けて弦を放しても大丈夫。どこを狙うかは、あなたの指先が覚えています。", "散向各处的箭，今天朝正中聚拢。铺开的那些事里，最想要的靶子是哪一个，其实你心里早有数。今天瞄准哪里，力道就落在哪里，朝最大的那个靶子放箭吧。该瞄哪里，你的指尖记得。"],
            ["화살이 흩어지는 건 실력보다 과녁이 많아서일 때가 있어요. 이것저것 손대느라 어느 하나도 깊어지지 않는다는 느낌이 요즘 스쳤을 거예요. 오늘은 과녁을 하나만 남기고 나머지를 잠시 내려놓아 보세요. 남긴 그 하나가 지금의 당신을 말해줘요.", "Sometimes arrows scatter not from lack of skill but from too many targets. It may have crossed your mind lately that with a hand in everything, nothing gets deep. Today, keep one target and set the rest down for now. The one you keep says something about who you are right now.", "矢が散るのは、腕前よりも的が多すぎるせいだったりします。あれこれ手を出すうちに、どれも深まっていない気がして、この頃ふとよぎったのではないでしょうか。今日は的をひとつだけ残して、ほかをしばらく下ろしてみて。残したそのひとつが、いまのあなたを物語ります。", "箭散，有时不怪功夫，怪靶子太多。什么都碰一碰，哪一样都没扎深的感觉，最近大概掠过你心头。今天只留一个靶子，其余暂放。留下的那一个，说明现在的你。"],
            ["활을 잘 쏘는 사람은 시위를 당긴 채 호흡부터 골라요. 서두르면 맞을 것도 빗나가는 법이라, 오늘은 쏘는 날보다 겨누는 날에 가까워요. 겨냥이 흔들리는 건 못해서가 아니라 아직 숨을 고르는 중이라서예요. 호흡이 잡히는 순간은 당신이 먼저 알아챌 거예요.", "A good archer draws the string and steadies the breath first. Rushing sends even sure shots wide, so today leans toward aiming, not loosing. A wavering aim doesn't mean you can't shoot. It means the breath is still settling. You'll be the first to know the moment it holds.", "弓の上手な人は、弦を引いたまま、まず呼吸を整えます。急げば当たるものも逸れてしまうので、今日は射る日というより、狙いを定める日に近いのです。狙いが揺れるのは下手だからではなく、まだ息を整えている途中だから。呼吸が定まる瞬間は、あなたが先に気づくはずです。", "善射的人，先在满弓时调匀呼吸。急了，本该中的也会偏。今天与其放箭，不如瞄准。准星晃，不是不行，是还在调息。呼吸稳下来的那一刻，你会最先察觉。"],
            ["과녁 앞에 섰다고 매번 쏴야 하는 건 아니에요. 맞혀야 한다는 마음이 요즘 어깨에 힘을 넣고 있었을 거예요. 오늘은 시위를 풀고 겨누는 자세만 확인해도 충분한 연습이 돼요. 활을 잠시 내려놓는 것도 궁수의 기술 가운데 하나예요.", "Standing before a target doesn't mean you owe it an arrow. The need to hit the mark has probably been stiffening your shoulders lately. Today, ease the string and simply check your stance. That already counts as practice. Setting the bow down for a while is one of an archer's skills too.", "的の前に立ったからといって、毎回射なくてもいいのです。当てなければという気持ちが、この頃肩に力を入れていたのではありませんか。今日は弦をゆるめて、構えを確かめるだけでも十分な稽古になります。弓をしばらく置くことも、射手の技のひとつです。", "站在靶前，不等于每次都得射。必须射中的念头，最近大概让肩膀绷紧了。今天松开弓弦，只确认姿势，也算扎实的一练。把弓暂且放下，也是弓手的功夫之一。"],
        ]),
        TarotCard(id: 22, name: ["선반 위 트로피", "The Trophy on the Shelf", "棚の上のトロフィー", "架上的奖杯"], icon: "Trophy", readings: [
            ["트로피는 받는 순간보다 다시 꺼내 보는 순간에 더 빛나는 법이에요. 별것 아니라며 스스로 선반 구석에 밀어둔 성취가 하나쯤 있지 않나요. 오늘은 그걸 앞줄로 옮기고 소리 내어 해냈다고 말해도 되는 날이에요. 그 말을 처음 들어야 할 사람은 다름 아닌 당신이에요.", "A trophy shines more when taken down again than when first received. Isn't there an achievement you pushed to a corner of the shelf as no big deal? Today you can move it to the front row and say out loud that you did it. The first person who needs to hear it is you.", "トロフィーは、もらう瞬間より、あとで取り出して眺める瞬間にいっそう輝くものです。大したことないと、自分で棚の隅へ押しやった成果がひとつくらいありませんか。今日はそれを前の列へ移して、やり遂げたと声に出してもいい日です。その言葉を最初に聞くべき相手は、ほかでもないあなたです。", "奖杯最亮的时刻，往往不是领的那一刻，是重新拿出来看的那一刻。有没有一个被你说着没什么、推到架子角落的成绩。今天把它挪到前排，出声说一句我做到了。最先该听到这句话的人，正是你。"],
            ["선반에는 늘 다음 트로피를 위한 빈칸이 남아 있어요. 지난 성취를 곱씹기보다 그 칸을 채울 일에 손을 대는 게 오늘과 어울려요. 시작이 거창할 필요는 없고, 착수했다는 사실만으로 칸에는 이름표가 붙어요. 무엇을 올릴지는 천천히 골라도 돼요.", "A shelf always keeps an empty space for the next trophy. Today suits putting your hands on what will fill that space, more than savoring the last one. The start doesn't need to be grand. The moment you begin, the space gets a name on it. What to place there, you can choose slowly.", "棚にはいつも、次のトロフィーのための空きがあります。過ぎた成果を噛みしめるより、その空きを埋めることに手をつけるのが今日に合っています。始まりは大げさでなくていい。着手したという事実だけで、その場所には名札がつきます。何を載せるかは、ゆっくり選んで大丈夫。", "架子上永远留着给下一座奖杯的空位。与其回味过去的成绩，不如对填上那个空位的事下手，这才合今天。开头不必隆重，动了手，空位上就贴上了名牌。放什么上去，慢慢挑。"],
            ["오늘은 트로피의 먼지를 닦는 날이에요. 새로 따내려 애쓰기보다 지나온 것들을 하나씩 세어보면, 생각보다 선반이 비어 있지 않다는 걸 알게 돼요. 걸음은 제자리 같아도 선반에는 쌓아온 게 있는 사람이 당신이에요. 닦다 보면 다음에 갈 곳도 보여요.", "Today is for dusting the trophies. Count what you've already gathered instead of straining for new ones, and the shelf turns out less empty than it looked. Your steps may feel unchanged, but you're someone with a stocked shelf. Keep polishing and the next destination comes into view.", "今日はトロフィーのほこりを払う日です。新しく取りにいこうと励むより、歩んできたものをひとつずつ数えてみると、棚が思ったより空いていないことに気づきます。足踏みのようでも、棚には積んできたものがある人、それがあなたです。磨いているうちに、次に向かう場所も見えてきます。", "今天是给奖杯掸灰的日子。先不急着添新的，把走过的一件件数过来，会发现架子并不像想的那么空。步子看似没动，你却是架上有积攒的人。擦着擦着，下一站也会显出来。"],
            ["트로피가 없는 계절에도 달리기는 계속돼요. 결과가 손에 잡히지 않아 마음이 가라앉던 요 며칠이 있었을지 몰라요. 오늘은 순위표를 접고, 달린 날은 달린 날대로 쳐주는 연습을 해보세요. 기록보다 오래 남는 건 달리는 습관이에요.", "The running continues even in seasons without trophies. There may have been days lately when no result would take shape in your hands. Today, fold up the rankings and practice crediting a day run as a day run. What outlasts the records is the habit of running.", "トロフィーのない季節にも、走ることは続いていきます。結果が手に残らなくて、気持ちが沈んでいた日々があったかもしれません。今日は順位表をたたんで、走った日は走った日として認めてあげる稽古をしてみて。記録より長く残るのは、走る習慣のほうです。", "没有奖杯的季节，跑步也在继续。这几天也许有过结果抓不到手、心情往下沉的时候。今天把排行榜合上，练习把跑过的日子按跑过算数。比纪录留得久的，是跑下去的习惯。"],
        ]),
        TarotCard(id: 23, name: ["선물 상자", "The Gift Box", "贈り物の箱", "礼物盒"], icon: "Gift", readings: [
            ["선물은 주는 손이 넉넉할 때 더 멀리 도착해요. 최근에 받았던 작은 호의 하나가 문득 떠오르는 날이 있죠. 오늘은 그 온기를 크게 돌려도 좋은 날이라, 마음먹은 호의를 아끼지 않아도 돼요. 누구에게 먼저 건넬지는 이미 떠올랐을 거예요.", "A gift travels farther when the giving hand is generous. Some days a small kindness you once received comes suddenly back to mind. Today you can return that warmth at full size, without rationing the goodwill you've been meaning to give. Who to hand it to first has probably already occurred to you.", "贈り物は、差し出す手にゆとりがあるとき、より遠くまで届きます。最近もらった小さな親切が、ふと思い浮かぶ日がありますよね。今日はそのぬくもりを惜しみなく巡らせていい日ですから、心に決めた親切を出し惜しみしなくて大丈夫。誰に先に手渡すかは、もう浮かんでいるのではないでしょうか。", "送出去的东西，给的手越大方，走得越远。最近收到的某个小小的好意，是不是会忽然想起来。今天可以把那份暖意放大了还回去，打定主意的好意不必省。先递给谁，你已经想到了。"],
            ["받은 선물의 리본은 풀었는데 답례는 건너뛴 것이 있지 않나요. 답례라고 해서 거창한 포장이 필요한 건 아니에요. 오늘은 받은 것들 가운데 하나를 골라 되건네기 좋은 날이에요. 작게 건넨 답례 하나가 다음 호의의 문을 열어줘요.", "Is there a gift whose ribbon you untied but whose thanks you skipped? A return gesture doesn't need grand wrapping. Today is good for choosing one thing you've received and passing something back. One small return opens the door to the next kindness.", "もらった贈り物のリボンはほどいたのに、お返しは飛ばしたままのものがありませんか。お返しといっても、立派な包みは要りません。今日はもらったものの中からひとつ選んで、返すのにいい日です。小さく手渡したお返しひとつが、次の親切の扉をあけてくれます。", "收到的礼物拆了缎带，回礼却跳过去的，有没有一件。回礼不需要隆重的包装。今天适合从收到的里面挑一件，轻轻递回去。小小的一份回礼，会替下一份好意开门。"],
            ["선물은 포장을 뜯는 속도만큼 빨리 사라지는 법이에요. 오늘은 서둘러 뜯기보다 리본부터 천천히 푸는 날이에요. 포장이 수수해 보이는 하루에도, 뜯어보면 작은 호의가 들어 있어요. 그걸 알아보는 눈이 오늘 당신이 받는 선물이에요.", "A gift disappears as fast as its wrapping is torn. Today, start with the ribbon and go slowly. Even a plain-looking day has a small kindness tucked inside once opened. The eye that recognizes it is the gift you receive today.", "贈り物は、包みをあける速さのぶんだけ早く消えてしまうものです。今日は急いで破るより、リボンからゆっくりほどく日。包みが地味に見える一日にも、あけてみれば小さな親切が入っています。それを見分ける目こそ、今日あなたが受け取る贈り物です。", "礼物消失的速度，和拆包装的速度一样快。今天别急着拆，先慢慢解缎带。看着朴素的一天，拆开来，里面也装着小小的好意。认得出它的眼睛，就是今天你收到的礼物。"],
            ["주는 기쁨에 익숙한 사람일수록 받는 일에는 서툴러요. 입으로는 괜찮다고 해도 속으로는 챙김이 고팠던 순간이 있었을 거예요. 오늘은 건네려는 손을 잠시 쉬게 하고, 오는 호의를 그냥 받아보세요. 고맙다는 말 한마디면 답례는 다 된 거예요.", "The more practiced you are at giving, the clumsier receiving can feel. There were probably moments you said you were fine while quietly wishing to be looked after. Today, let the giving hand rest and simply receive what comes. One thank you completes the exchange.", "あげる喜びに慣れた人ほど、受け取ることには不器用です。口では大丈夫と言いながら、内心はいたわりに飢えていた瞬間があったはず。今日は差し出そうとする手をしばらく休ませて、来る親切をそのまま受け取ってみて。ありがとうのひと言で、お返しは済んでいるのです。", "习惯给予的人，往往不善于接受。嘴上说不用，心里其实也馋过被照顾的时刻。今天让递出去的手歇一歇，来的好意就那么收下。一句谢谢，回礼就算齐了。"],
        ]),
        TarotCard(id: 24, name: ["동전 한 닢", "The Single Coin", "一枚の硬貨", "硬币"], icon: "Coins", readings: [
            ["저금통이 묵직해지는 소리는 어느 날 갑자기 들려요. 티도 안 난다고 여겼던 반복이 사실은 무게를 갖추는 중이었던 거예요. 오늘은 쌓아온 것을 믿고 꺼내 써도 되는 날이에요. 어디에 쓸지 정하는 즐거움은 모아온 사람의 몫이에요.", "The heft of a savings jar announces itself all at once. The repetition that seemed to show nothing was gathering weight all along. Today you can trust what has stacked up and draw on it. Deciding where to spend it is the saver's pleasure, and it's yours.", "貯金箱が重くなる音は、ある日ふいに聞こえてくるものです。実りがないと思っていた繰り返しが、実は重みを備えている最中でした。今日は積んできたものを信じて、取り出して使ってもいい日です。何に使うか決める楽しみは、貯めてきた人のものです。", "储蓄罐变沉的声音，总是某一天突然听见的。以为毫无起色的重复，其实一直在长分量。今天可以信着攒下的东西，取出来用了。用在哪儿的乐趣，归攒下它的人。"],
            ["동전 한 닢은 가볍지만 거르지 않는 손은 무거워요. 오늘 몫의 한 닢이 무엇인지, 짚이는 데가 하나 있을 거예요. 대단해 보이지 않아도 오늘 넣은 그 한 닢이 내일의 소리를 바꿔요. 지금 손에 쥐고 있는 것부터 넣어보세요.", "One coin is light, but a hand that never skips carries weight. You can probably guess what today's coin is. It may not look like much, yet the one you drop in today changes tomorrow's sound. Start with what's already in your hand.", "硬貨は軽くても、欠かさない手は重いのです。今日のぶんのひと枚が何なのか、思い当たるところがひとつあるはず。立派に見えなくても、今日入れたそのひと枚が、明日の音を変えます。いま手の中にあるものから、入れてみてください。", "一枚硬币很轻，从不间断的手很重。今天该投的那一枚是什么，你心里大概有数。看着不起眼，今天投进去的这一枚，会改变明天的响声。先从手里攥着的投起。"],
            ["가끔은 저금통을 흔들어 소리만 들어보는 날도 필요해요. 늘어난 게 없어 보여도 소리는 조금씩 낮고 묵직해지고 있어요. 무게는 그대로 같아도 안에서는 쌓임이 이어지고 있다는 뜻이에요. 오늘은 붓기보다 가늠해보는 날이에요.", "Some days are for shaking the jar and just listening. Even when nothing seems to have grown, the sound is turning lower and fuller. The weight feels the same, but inside, the stacking goes on. Today is for gauging, not depositing.", "ときには貯金箱を振って、音だけ確かめる日も要ります。増えていないようでも、音は少しずつ低く、重くなっています。重さは同じに見えても、中では積み重なりが続いているということ。今日は注ぐより、推し量る日です。", "偶尔也需要只摇一摇储蓄罐、听听声音的日子。看着没见多，声音却在一点点变低变沉。分量像是没变，里面的积攒却没停。今天不投，掂一掂就好。"],
            ["쌓는 일에도 숨 고르기가 필요해요. 하루 거른다고 저금통이 비어버리지는 않아요. 거르면 안 된다는 마음이 요 며칠 당신을 몰아붙였을지 몰라요. 오늘은 붓는 손을 잠시 쉬게 하고, 애초에 모으기 시작한 이유만 가만히 떠올려 보세요.", "Saving needs its breathing room too. Skipping one day doesn't empty the jar. The rule of never missing a day may have been driving you hard lately. Today, let the depositing hand rest, and just recall why you started saving at all.", "積むことにも、息継ぎが要ります。一日空けたからといって、貯金箱が空になるわけではありません。欠かしてはいけないという気持ちが、ここ数日あなたを追い立てていたかもしれません。今日は注ぐ手を休ませて、そもそも貯め始めた理由だけ、そっと思い出してみてください。", "积攒这件事也需要换气。断一天，罐子不会空。一天都不能断的念头，这几天也许一直在逼你。今天让投币的手歇歇，只静静想想当初为什么开始攒。"],
        ]),
        TarotCard(id: 25, name: ["오래된 서랍", "The Old Drawer", "古い引き出し", "旧抽屉"], icon: "Archive", readings: [
            ["서랍을 통째로 빼서 볕에 내놓아도 되는 날이에요. 언젠가 하려고 넣어두고는 그대로 잊은 것이 당신 서랍에도 있을 거예요. 오늘은 묵힌 것들을 꺼내 크게 정리해도 어수선해지지 않아요. 남길 것과 보낼 것을 가르는 손이 가벼울 거예요.", "A day you can pull the whole drawer out into the sun. Your drawer holds things too, tucked away for someday and then forgotten. Today you can take out what's been sitting and sort it in bulk without things turning chaotic. The hand that splits keep from release will feel light.", "引き出しをそっくり抜いて、日に当ててもいい日です。いつかやろうとしまい込んで、そのまま忘れたものが、あなたの引き出しにもあるはず。今日は寝かせてきたものを取り出して思いきって整理しても、散らかりません。残すものと手放すものを分ける手が、軽やかなはずです。", "可以把整个抽屉抽出来晒太阳的日子。写着改天再说就放进去、然后忘掉的东西，你的抽屉里也有。今天把压箱底的都拿出来，痛痛快快整理一场，也不会乱。分出留下的和送走的，那双手会很轻快。"],
            ["서랍 정리는 맨 위 칸 하나로 시작하면 돼요. 다 열자니 엄두가 안 나서 계속 닫아두었던 마음, 요즘 한 번쯤 스쳤을 거예요. 오늘은 딱 한 칸만 열어 안을 들여다보세요. 거기서 나온 것 하나가 다음 칸을 열게 해줘요.", "Drawer-cleaning starts with just the top tier. The thought of opening everything at once is exactly what kept it shut, and that's probably crossed your mind lately. Today, open one tier only and look inside. One thing found there will open the next tier for you.", "引き出しの整理は、いちばん上の段ひとつから始めればいいのです。全部あけるのは気が重くて、閉めたままにしてきた気持ち、この頃よぎりませんでしたか。今日はひと段だけあけて、中をのぞいてみて。そこから出てきたひとつが、次の段をあけさせてくれます。", "整理抽屉，从最上面一格开始就行。全都打开没那个劲头，于是一直关着的心情，最近大概闪过。今天只开一格，看看里面。从那里拿出的一样东西，会替你打开下一格。"],
            ["서랍은 열지 않고 목록만 떠올려도 정리가 시작돼요. 무엇을 넣어두었는지 헤아리다 보면 아직 쓸모 있는 것과 놓아도 되는 것이 머릿속에서 먼저 나뉘어요. 오늘은 손 대신 눈으로 정리하는 날이에요. 목록이 선명해지면 여는 날은 절로 와요.", "Sorting begins even without opening the drawer, just by listing what's inside. As you tally what you put away, the still-useful and the ready-to-release start separating in your head first. Today is for sorting with the eyes, not the hands. When the list comes clear, the opening day arrives on its own.", "引き出しは、あけなくても中身を思い浮かべるだけで整理が始まります。何をしまっていたか数えるうちに、まだ使えるものと手放していいものが、頭の中で先に分かれていきます。今日は手ではなく目で片づける日。目録がはっきりすれば、あける日はおのずと来ます。", "不开抽屉，只在心里过一遍清单，整理也就开始了。数着放了些什么，还有用的和可以放手的，会先在脑子里分开。今天用眼睛整理，不用手。清单清楚了，开抽屉的日子自己会来。"],
            ["서랍은 오늘도 닫아두어도 괜찮아요. 정리해야 한다는 생각이 짐이 되면 서랍보다 마음이 먼저 무거워져요. 넣어둔 것들은 어디로도 도망가지 않고 제자리에서 얌전히 기다려요. 오늘은 서랍 앞을 그냥 지나쳐도 되는 날이에요.", "The drawer can stay closed today too. When the thought of needing to organize becomes a load, the mind grows heavy before the drawer does. Nothing you've put away is going anywhere. It waits quietly in place. Today you're allowed to walk right past it.", "引き出しは、今日も閉めたままで大丈夫です。片づけなければという考えが荷物になると、引き出しより先に心が重くなります。しまったものはどこへも逃げず、その場所でおとなしく待っています。今日は引き出しの前を、そのまま通り過ぎてもいい日です。", "抽屉今天继续关着也没关系。必须整理的念头一旦变成负担，心会比抽屉先沉。放进去的东西哪儿也不去，乖乖在原地等着。今天从抽屉前走过去，就走过去吧。"],
        ]),
        TarotCard(id: 26, name: ["손글씨 목록", "The Handwritten List", "手書きのリスト", "手写清单"], icon: "Clipboard", readings: [
            ["줄을 죽죽 그어 지우는 손맛이 좋은 날이에요. 머릿속에만 굴리던 일들도 종이에 옮기는 순간부터 눈에 띄게 가벼워져요. 오늘은 몰아서 해치워도 지치지 않는 흐름이라, 쌓여 있던 줄들을 연달아 지워도 좋아요. 끝줄까지 그은 종이를 구기는 기분은 당신 몫이에요.", "A day when crossing lines off feels especially good. Things that only circled your head turn visibly lighter the moment they land on paper. Today's flow lets you knock items out in a run without wearing down, so strike through the stacked lines one after another. The pleasure of crumpling a finished page is yours.", "線を引いて消していく手ごたえが、気持ちいい日です。頭の中で転がすだけだったことも、紙に移した瞬間から目に見えて軽くなります。今日はまとめて片づけても疲れない流れですから、溜まっていた行を続けざまに消してもいい。最後の行まで引き終えた紙を丸める気分は、あなたのものです。", "唰唰划掉时手感痛快的日子。只在脑子里打转的事，落到纸上的那一刻就轻了大半。今天是一口气划下去也不累的势头，把攒下的行一条条划掉也行。把划到最后一行的纸揉成一团的那份痛快，归你。"],
            ["목록의 힘은 맨 윗줄에 있어요. 다 해내려는 마음보다 첫 줄 하나를 지우는 손이 하루를 끌고 가요. 머릿속에서 며칠째 맴돌던 그 일, 아마 이미 맨 위에 적혀 있을 거예요. 오늘은 다른 줄 말고 그 한 줄부터 그어보세요.", "A list's power lives in its top line. One first line crossed off pulls the day along better than the wish to finish everything. The task that's been circling your head for days is probably already written at the top. Today, skip the other lines and strike that one.", "リストの力は、いちばん上の行にあります。全部やり遂げようとする気持ちより、最初の行をひとつ消す手が、一日を引っぱっていくのです。頭の中で何日も回っていたあのこと、たぶんもういちばん上に書かれています。今日はほかの行ではなく、その行から消してみて。", "清单的力量在最上面那行。比起全部做完的心，划掉第一行的手才拉得动一天。那件在脑子里转了好几天的事，多半已经写在最上面了。今天别的先放放，从那一行划起。"],
            ["오늘은 줄을 지우기보다 다시 세우는 날이에요. 급해 보이는 것과 정말 중요한 것이 섞여 있으면 손보다 마음이 먼저 지쳐요. 목록을 옮겨 적으며 순서만 바꿔도 하루의 결이 달라져요. 어떤 줄을 위로 올릴지는 당신이 정해요.", "Today is for reordering the list, not crossing it off. When the urgent-looking and the truly important sit mixed together, the heart tires before the hands do. Just rewriting the list in a new order changes the grain of the day. Which line moves up is your call.", "今日は行を消すより、並べ直す日です。急ぎに見えるものと本当に大事なものが混ざっていると、手より先に心が疲れます。リストを書き写しながら順番を入れ替えるだけでも、一日の手ざわりが変わります。どの行を上に上げるかは、あなたが決めることです。", "今天不划行，重排行。看着急的和真正要紧的混在一起，手还没累，心先累。把清单重新誊一遍，只换换顺序，一天的纹理就不一样。哪一行往上提，你说了算。"],
            ["목록은 채우라고만 있는 게 아니라 빼라고도 있어요. 다 해내지 못한 줄들이 마음에 얹혀 있던 요 며칠이었을 거예요. 오늘은 한 줄을 골라 지우지 말고 그냥 빼보세요. 하지 않기로 정하는 것도 목록을 다루는 기술이에요.", "A list isn't only for filling. It's also for removing. Unfinished lines have probably been sitting on your chest these past few days. Today, choose one line and take it out rather than cross it out. Deciding not to do something is a list skill too.", "リストは埋めるためだけでなく、減らすためにもあります。やりきれなかった行が胸につかえていた日々だったかもしれません。今日はひと行選んで、消すのではなく、外してみて。やらないと決めることも、リストの扱い方のひとつです。", "清单不只是用来填的，也是用来减的。这几天，没做完的那些行大概一直压在心上。今天挑一行，不划掉，直接拿掉。决定不做，也是使用清单的功夫。"],
        ]),
        TarotCard(id: 27, name: ["키 재던 벽", "The Measuring Wall", "背くらべの柱", "量身高的墙"], icon: "Chart", readings: [
            ["벽에 등을 대보면 눈금이 훌쩍 올라가 있는 날이 있어요. 제자리걸음 같던 요즘이 사실은 자라는 중이었다는 뜻이에요. 오늘은 자란 키에 맞는 옷을 꺼내 입어도 되는 날이라, 예전 기준으로 자신을 재지 않아도 돼요. 커진 만큼의 자리를 차지하는 건 당신의 몫이에요.", "Some days you stand against the wall and the mark has jumped. What felt like standing still lately was growing all along. Today you can dress for the height you've reached and stop measuring yourself against the old line. Taking up the room you've grown into is your part.", "柱に背中を当ててみると、印がぐんと上がっている日があります。足踏みのようだったこの頃が、実は育っている最中だったということ。今日は伸びた背丈に合う服を出して着てもいい日ですから、以前の物差しで自分を測らなくて大丈夫。大きくなったぶんの場所を占めるのは、あなたの役目です。", "有些日子往墙上一靠，刻度一下子高了一截。看着像原地踏步的这阵子，其实一直在长。今天可以穿上合了新身量的衣裳，不必再用旧尺码量自己。长了多少，就去占多少地方，这是你的份。"],
            ["키는 한 번에 크지 않고 눈금 하나씩 자라요. 오늘은 눈금 하나만큼만 서보는 날이에요. 어제보다 아주 조금 어려운 것에 손을 대면, 벽의 연필 자국은 자기도 모르는 사이 올라가 있어요. 어디에 까치발을 디딜지는 당신이 골라요.", "Height doesn't come all at once. It comes one mark at a time. Today, stand just one mark taller. Reach for something slightly harder than yesterday and the pencil line on the wall climbs while you're not looking. Where to place your tiptoes is yours to pick.", "背丈はいちどには伸びず、目盛りひとつずつ育ちます。今日は目盛りひとつぶんだけ、背伸びしてみる日。昨日よりほんの少し難しいことに手をかければ、柱の鉛筆の印は、知らないうちに上がっています。どこにつま先を立てるかは、あなたが選んでください。", "个子不是一下子长的，是一格一格长的。今天只站高一格。碰一碰比昨天难一点点的事，墙上的铅笔印会在不知不觉间上移。踮脚踩在哪里，你来挑。"],
            ["오늘은 벽에 등을 대고 가만히 서보는 날이에요. 자랐는지 아닌지 조바심 내지 않고 지금 키를 확인만 해두는 거예요. 스스로는 그대로 같아도 등 뒤의 벽은 달라진 걸 알고 있어요. 확인한 눈금은 다음 걸음의 기준이 돼요.", "Today, just stand with your back against the wall. No fretting over whether you've grown. Simply take today's measurement and note it. You may feel unchanged, but the wall behind you knows what's different. A mark confirmed becomes the baseline for the next step.", "今日は柱に背中を当てて、静かに立ってみる日です。伸びたかどうか気をもまずに、いまの背丈を確かめておくだけ。自分では変わらない気がしても、背中の柱は違いを知っています。確かめた目盛りは、次の一歩の物差しになります。", "今天靠着墙静静站一会儿。不为长没长着急，只把现在的高度记下来。自己觉得没变，背后的墙知道变了。记下的刻度，会成为下一步的基准。"],
            ["키는 매일 재면 자라는 게 보이지 않는 법이에요. 요즘 자꾸 스스로를 눈금 위에 세우고 있진 않았나요. 남과 견주는 눈금이라면 더더욱 내려와도 돼요. 오늘은 벽에서 한 발 떨어져 재는 일 말고 자라는 일에 몸을 두면, 눈금은 시간이 대신 그어줘요.", "Measure every day and the growing stays invisible. Have you been standing yourself against the ruler a little too often? If the ruler compares you to someone else, step down from it all the more. Today, stand away from the wall and put your time into growing, not measuring. Time will draw the next mark for you.", "背丈は、毎日測ると育ちが見えなくなるものです。この頃、自分をしきりに目盛りの上へ立たせていませんでしたか。人と見比べる目盛りなら、なおさら降りて大丈夫。今日は柱からひと足離れて、測ることではなく育つことに身を置けば、目盛りは時間が代わりに刻んでくれます。", "个子天天量，反而看不见长。最近是不是老把自己架到刻度上。要是拿来跟别人比的刻度，更可以下来了。今天离墙远一步，别管量，把身子放进生长里，刻度让时间替你画。"],
        ]),
        TarotCard(id: 28, name: ["바람", "The Wind", "風", "风"], icon: "Wind", readings: [
            ["창을 활짝 열어도 되는 날이에요. 방 안 공기가 무거웠다는 건 창을 연 다음에야 알게 되죠. 요즘 어딘가 답답했다면 그건 바람이 불어올 자리가 생겼다는 신호이기도 해요. 큰 변화의 바람을 방 안 가득 들이고, 무엇을 바꿀지는 당신이 정하세요.", "A day you can throw the window wide. You only learn how heavy the room's air was after opening it. If things have felt stuffy lately, that's also a sign that space has opened for wind to come through. Let the big change blow through the whole room, and decide for yourself what it rearranges.", "窓を大きくあけてもいい日です。部屋の空気が重かったことは、窓をあけたあとにようやくわかるもの。この頃どこか息苦しかったなら、それは風の入る場所ができた合図でもあります。大きな変化の風を部屋いっぱいに入れて、何を変えるかはあなたが決めてください。", "可以把窗全部敞开的日子。屋里空气有多闷，往往开了窗才知道。若最近哪里堵得慌，那也是风有了进来的位置的信号。让变化的风灌满屋子，改什么，你定。"],
            ["공기를 바꾸는 데 창 전부가 필요하진 않아요. 문틈 하나만 열려도 방의 공기는 천천히 새것으로 바뀌어요. 오늘은 늘 하던 것들 가운데 하나만 다르게 해보는 날이에요. 어느 틈을 먼저 열지 고르는 일부터 이미 환기는 시작돼요.", "Changing the air doesn't take every window. One gap in the door and the room slowly turns over to new air. Today, do just one of your usual things differently. Even choosing which gap to open first, the airing has already begun.", "空気を入れ替えるのに、窓の全部は要りません。戸の隙間ひとつあいていれば、部屋の空気はゆっくり新しくなります。今日はいつもしていることの中から、ひとつだけ違うやり方を試す日です。どの隙間から先にあけるか、選ぶところからもう換気は始まっています。", "换空气不需要整扇窗。门缝开一条，屋里的空气也会慢慢换新。今天从惯常做的事里挑一件，换个做法。挑先开哪条缝的时候，通风就已经开始了。"],
            ["바람을 거스르며 걷는 날이 있고 바람을 읽으며 걷는 날이 있어요. 오늘은 읽는 쪽이에요. 주변의 흐름이 어느 방향으로 부는지 가만히 느껴보면, 애쓰지 않아도 밀려가는 길이 보여요. 돛을 올릴지 말지는 방향을 안 다음에 정해도 돼요.", "Some days you walk against the wind, and some days you read it. Today is for reading. Feel which way things around you are moving, and a path appears that carries you without strain. Whether to raise the sail can be decided after you know the direction.", "風に逆らって歩く日があれば、風を読んで歩く日もあります。今日は読む側です。まわりの流れがどちらへ吹いているのか静かに感じてみると、力まなくても運ばれていく道が見えてきます。帆を上げるかどうかは、向きを知ってから決めても遅くありません。", "有顶风走的日子，也有读风的日子。今天是读的那种。静静感觉周围的流向往哪边吹，不用使劲也被推着走的路会显出来。扬不扬帆，等知道了方向再定。"],
            ["바람이 센 날에는 창을 반쯤만 여는 게 지혜예요. 흔들리는 것들을 붙잡아 두고, 새로 벌이기보다 지금 있는 것을 여미는 날이에요. 변화가 더디다고 느꼈다면 그건 멈춘 게 아니라 바람을 피하는 중인 거예요. 창은 바람이 잦아든 뒤에 활짝 열어도 늦지 않아요.", "On a strong-wind day, wisdom opens the window halfway. Steady what's rattling, and tend what you have rather than starting something new. If change has felt slow, you haven't stopped. You've been sheltering. The window can open wide after the wind settles, and that won't be too late.", "風の強い日は、窓を半分だけあけるのが知恵です。揺れるものを押さえて、新しく広げるより、いまあるものの襟元を整える日。変化が鈍いと感じていたなら、それは止まったのではなく、風をよけている最中です。窓は、風がやんでから大きくあけても遅くないのです。", "风大的日子，窗开一半才是智慧。把晃动的东西按住，比起另起炉灶，今天先把手头的掖好。若觉得变化太慢，那不是停了，是在避风。窗，等风歇了再敞不迟。"],
        ]),
        TarotCard(id: 29, name: ["보름달", "The Full Moon", "満月", "满月"], icon: "Moon", readings: [
            ["달이 가장 환하게 차오른 밤이에요. 미뤄두었던 일을 벌이기에 이만한 조명이 없어요. 좋았다 나빴다 하던 요즘의 기복도 사실은 차오르는 리듬의 일부였던 거예요. 환한 김에 무엇을 펼칠지, 달빛 아래에서 당신이 고르면 돼요.", "The moon is at its fullest tonight. For taking up something postponed, there's no better lighting. Even the recent ups and downs were part of the filling rhythm all along. What to unfold under all this brightness, you choose by moonlight.", "月がいちばん明るく満ちた夜です。先延ばしにしてきたことを広げるのに、これほどの明かりはありません。良かったり沈んだりしていたこの頃の波も、実は満ちていくリズムの一部でした。明るいうちに何を広げるか、月明かりの下であなたが選べばいいのです。", "月亮涨到最满的夜晚。要铺开搁置的事，没有比这更好的照明。近来忽好忽坏的起伏，其实也是渐盈节奏的一部分。趁着亮，摊开什么，在月光下由你挑。"],
            ["달은 하루아침에 차지 않고 조금씩 부풀어요. 오늘은 차오르는 쪽에 몸을 맞추는 날이에요. 채우고 싶던 것 하나를 골라 어제보다 아주 조금만 더해보세요. 달이 차오르는 그 속도면 충분하다는 걸 몸이 먼저 알게 될 거예요.", "The moon doesn't fill in a night. It swells little by little. Today, set yourself to the waxing side. Choose one thing you've wanted to fill and add just a little more than yesterday. Your body will learn that the moon's pace is enough.", "月はひと晩では満ちず、少しずつふくらみます。今日は満ちていく側に体を合わせる日です。満たしたいものをひとつ選んで、昨日よりほんの少しだけ足してみて。月が満ちていくあの速さで十分だということを、体が先にわかってくれるはずです。", "月亮不是一夜圆的，是一点点鼓起来的。今天把自己贴到渐盈的那一侧。挑一件想填满的事，比昨天只多加一点。月亮涨的那个速度就够用，身体会先明白。"],
            ["달을 올려다보는 것만으로 넉넉한 밤이 있어요. 차오르는 중인지 기우는 중인지 굳이 판정하지 않아도 리듬은 제 갈 길을 가요. 마음이 오르내리는 것도 달의 일과 닮아 있어요. 오늘은 리듬을 고치려 하지 말고 그냥 바라봐 주세요.", "Some nights, looking up at the moon is plenty. Waxing or waning, the rhythm keeps its road without your ruling on it. The heart's rising and falling resembles the moon's work too. Today, don't fix the rhythm. Just watch it.", "月を見上げるだけで満ち足りる夜があります。満ちる途中か欠ける途中か、わざわざ見立てなくても、リズムは自分の道を行きます。心が上がり下がりするのも、月の営みに似ています。今日はリズムを直そうとせず、ただ眺めていてください。", "有的夜晚，抬头看看月亮就很富足。在盈还是在亏，不必判定，节奏自会走自己的路。心情起起落落，也和月亮的活儿相像。今天不修节奏，看着就好。"],
            ["차는 것만큼 기우는 것도 달의 일이에요. 줄어드는 시기를 잘못이라 여기면 밤이 길게 느껴져요. 내색하지 않았어도 속으로는 애쓰고 있었다는 걸 달빛은 알고 있어요. 오늘은 차오르려 애쓰지 말고 어두워진 만큼 쉬어가세요.", "Waning is as much the moon's work as waxing. Call the shrinking season a fault and the night feels long. Even unspoken, the effort you've been making, the moonlight has seen. Tonight, don't strain to fill. Rest as much as it has dimmed.", "満ちることと同じくらい、欠けることも月の営みです。減っていく時期を過ちのように思うと、夜が長く感じられます。顔に出さなくても、内側では踏ん張っていたことを、月明かりは知っています。今日は満ちようと励まずに、暗くなったぶんだけ休んでいってください。", "亏，和盈一样，都是月亮的本分。把变小的时节当成过错，夜会显得很长。就算没有声张，一直在硬撑这件事，月光是知道的。今天别努力去盈，暗下来多少，就歇多少。"],
        ]),
        TarotCard(id: 30, name: ["반딧불", "The Firefly", "蛍火", "萤火"], icon: "Sparkle", readings: [
            ["반딧불이 유난히 잦게 반짝이는 밤이에요. 스치듯 지나갔던 좋은 예감이나 아이디어가 요 며칠 새 있었을 거예요. 오늘은 그 빛을 크게 좇아도 되는 날이라, 즉흥처럼 보이는 걸음도 길이 돼요. 어느 불빛을 따라갈지는 당신의 눈이 이미 골라뒀어요.", "The fireflies are blinking often tonight. A good hunch or idea probably brushed past you in recent days. Today you can chase that light at full stride, and even steps that look impulsive become a path. Which glow to follow, your eyes have already picked.", "蛍がひときわ頻繁にまたたく夜です。かすめて過ぎたいい予感やひらめきが、ここ数日のうちにあったはず。今日はその光を思うまま追いかけてもいい日で、思いつきに見える足取りも道になります。どの明かりについていくかは、あなたの目がもう選んでいます。", "萤火眨得格外勤的夜晚。这几天是不是有掠过就没影的好预感或好点子。今天可以放开去追那点光，看着即兴的脚步也能走成路。跟哪一点光走，你的眼睛早就选好了。"],
            ["반딧불은 잡으려는 손보다 적어두는 손에 오래 남아요. 반짝하고 사라진 생각이 아깝게 느껴진 적이 최근에 있었죠. 오늘은 스치는 빛을 메모로 붙잡고, 그 가운데 하나만 골라 실행해보세요. 적힌 반짝임은 꺼지지 않아요.", "A firefly lasts longer in the hand that writes it down than the hand that grabs at it. You've probably felt the pinch of a bright thought flashing and vanishing lately. Today, pin the passing lights with a note, then choose just one to act on. A spark written down doesn't go out.", "蛍は、捕まえようとする手より、書き留める手に長くとどまります。ぱっと光って消えた考えを惜しく思ったこと、最近ありましたよね。今日はかすめる光をメモでつかまえて、その中からひとつだけ選んで動いてみて。書き留めたまたたきは、消えません。", "萤火在捕捉的手里留不住，在记下来的手里留得久。一闪而过的念头让人惋惜的时刻，最近大概有过。今天把掠过的光抄进备忘，再从里面只挑一件去做。写下来的闪光，不会灭。"],
            ["반딧불을 보려면 먼저 어둠에 눈을 맞춰야 해요. 밝은 곳만 좇으면 정작 작은 빛을 놓치기 쉬워요. 오늘은 쫓아다니기보다 가만히 서서 눈을 고르는 날이에요. 어둠이 익숙해질 즈음, 보이지 않던 것들이 하나씩 떠올라요.", "To see fireflies, first let your eyes adjust to the dark. Chase only the bright places and the small lights slip by. Today is for standing still and letting your vision settle, not for running around. As the dark grows familiar, things unseen begin to surface one by one.", "蛍を見るには、まず暗さに目を慣らすことです。明るい場所ばかり追うと、かえって小さな光を見落とします。今日は追い回すより、静かに立って目を整える日。暗さになじんできた頃、見えなかったものがひとつずつ浮かんできます。", "想看见萤火，先得让眼睛习惯黑。只追亮处，反而漏掉小的光。今天不追着跑，站定，把眼睛调匀。等黑暗看熟了，原先看不见的会一点点浮上来。"],
            ["반짝임을 붙잡으려 뛰다 보면 밤길에 발을 헛디디기 쉬워요. 좋아 보이는 것마다 좇느라 숨이 찼던 요즘이었을지 몰라요. 오늘은 스쳐 가는 빛은 그저 스쳐 가게 두어도 되는 날이에요. 앉아 있는 사람 곁에도 반딧불은 날아와요.", "Run after every flicker and night paths turn your ankles. You may have been out of breath lately, chasing whatever glinted. Today, passing lights can simply be let pass. Fireflies also drift toward the one who sits still.", "またたきをつかまえようと走ると、夜道では足を踏み外しやすいのです。良さそうなものを追いかけ続けて、息が切れていた日々だったかもしれません。今日はかすめていく光は、かすめるままにしておいていい日です。座っている人のそばにも、蛍は飛んできます。", "追着闪光跑，夜路容易崴脚。近来也许正是这样，见着好的就追，追得喘不上气。今天让掠过去的光就那么掠过去。坐着的人身边，萤火也会飞来。"],
        ]),
        TarotCard(id: 31, name: ["번개", "The Lightning", "稲妻", "闪电"], icon: "Zap", readings: [
            ["번개가 치면 어두웠던 풍경이 한순간에 또렷해져요. 최근 번뜩 스쳤던 그 확신, 우연이 아니었을 수 있어요. 오늘은 직감에 무게를 실어도 되는 날이라, 머리로 다 설명되지 않아도 몸이 아는 쪽으로 가도 좋아요. 섬광이 비춘 방향을 걷는 건 당신의 발이에요.", "When lightning strikes, the dark landscape sharpens in an instant. That flash of certainty you had recently may not have been chance. Today you can put weight on your instinct, and even what the head can't fully explain, the body may know. The feet that walk the lit direction are yours.", "稲妻が走ると、暗かった景色がいちどきに際立ちます。最近ひらめいたあの確信、偶然ではなかったのかもしれません。今日は直感に重みを載せていい日ですから、頭で説明しきれなくても、体でわかるほうへ進んで大丈夫。閃光が照らした方角を歩くのは、あなたの足です。", "闪电一亮，黑着的景色瞬间清晰。最近那道一闪而过的笃定，未必是偶然。今天可以给直觉压上分量，就算脑子还没解释周全，也可以往身体认得的方向走。沿着闪光照亮的方向迈步的，是你的脚。"],
            ["번개의 빛은 짧아서, 본 것은 사라지기 전에 적어둬야 해요. 순간 또렷했다가 이내 흐려진 생각이 최근에 있었죠. 오늘은 그걸 다시 붙잡아 메모하고, 작게라도 첫 동작을 만들어보세요. 천둥은 움직이는 사람 뒤에서 울려요.", "Lightning is brief, so what it shows has to be written down before it fades. There was probably a thought that stood vivid for a moment and then blurred. Today, catch it again in a note and shape the first small motion. Thunder rolls behind the person who moves.", "稲妻の光は短いので、見たものは消える前に書き留めるものです。一瞬はっきりして、すぐかすんだ考えが最近ありましたよね。今日はそれをもう一度つかまえてメモして、小さくてもいいから最初の動きをつくってみて。雷鳴は、動く人の背中で鳴るのです。", "闪电的光很短，看见的东西要趁消失前记下来。那种瞬间清楚、转眼又模糊的念头，最近有过吧。今天把它重新抓住写下来，再小也做出第一个动作。雷声，总在动起来的人身后响。"],
            ["번개가 지나간 뒤에는 천둥을 기다리는 시간이 있어요. 번쩍인 생각을 바로 판정하지 말고 여운이 어디까지 울리는지 들어보는 날이에요. 겉으로는 잠잠해 보여도 속에서는 소리가 이동하는 중이에요. 서두르지 말고 귀만 열어두면 돼요.", "After lightning comes the time of waiting for thunder. Don't rule on the flash right away. Today is for listening to how far the echo carries. It may look quiet on the surface, but inside, the sound is still traveling. No hurry. Just keep an ear open.", "稲妻が走ったあとには、雷鳴を待つ時間があります。ひらめいた考えをすぐ判定せず、余韻がどこまで響くのか聴いてみる日です。表向きは静かに見えても、内側では音が移動している最中。急がず、耳だけあけておけば大丈夫です。", "闪电过后，有一段等雷声的时间。刚闪过的念头别急着判定，听听余音能荡到哪里。表面风平浪静，声音正在里面赶路。不急，把耳朵开着就行。"],
            ["섬광이 너무 밝으면 잠시 눈을 감는 게 순서예요. 마음이 확 끌리는 생각일수록 한 박자 늦춰볼 만해요. 오늘은 몰아치는 결정 대신 하룻밤 재워두는 쪽을 고르는 날이에요. 그게 정말 번개였다면 내일 다시 봐도 그 자리는 환할 거예요.", "When the flash is too bright, closing your eyes for a moment is the right order. The more a thought pulls at you, the more it can stand one beat of delay. Today, choose the overnight rest over the rushed decision. If it really was lightning, the spot will still be lit when you look tomorrow.", "閃光がまぶしすぎるときは、いったん目を閉じるのが順序です。心が強く引かれる考えほど、ひと拍子遅らせてみる値打ちがあります。今日はたたみかける決断ではなく、ひと晩寝かせるほうを選ぶ日。それが本物の稲妻だったなら、明日見直してもその場所は明るいままのはずです。", "光太亮的时候，先闭一闭眼才是正理。越是让心猛地一动的念头，越值得缓一拍。今天不做扑上去的决定，选放一夜的那边。若它真是闪电，明天再看，那里依然是亮的。"],
        ]),
        TarotCard(id: 32, name: ["깃발", "The Flag", "旗", "旗帜"], icon: "Flag", readings: [
            ["봉우리에 깃발이 어울리는 날이에요. 여기까지 왔다고 선언해도 누구도 이르다 하지 않아요. 스스로는 아직 멀었다 여겨도, 돌아보면 출발점이 보이지 않을 만큼 걸어온 사람이 당신이에요. 깃발을 꽂고 바람에 펄럭이게 두세요.", "A day when the summit suits a flag. Declaring that you've come this far, no one would call it early. You may feel you have a long way to go, but look back and the starting point is out of sight. That's how far you've walked. Plant the flag and let it snap in the wind.", "頂に旗が似合う日です。ここまで来たと宣言しても、誰も早すぎるとは言いません。自分ではまだまだだと思っていても、振り返れば出発点が見えないほど歩いてきた人、それがあなたです。旗を立てて、風にはためかせておいてください。", "峰顶配得上一面旗的日子。宣布我走到这里了，没有人会说太早。自己觉得还差得远，可回头看看，出发点已经远得看不见了，走过这些路的人是你。把旗插上，让它在风里响。"],
            ["깃발은 꽂는 순간보다 다음 자리를 정하는 순간에 힘이 생겨요. 지금 선 자리를 표시했다면 이제 시선을 조금 앞으로 옮길 차례예요. 오늘은 다음 깃발 자리를 하나 정하고 그쪽으로 첫걸음을 옮기는 날이에요. 거리는 짧아도 방향이 생기면 걸음이 달라져요.", "A flag gains its force less in the planting than in choosing the next spot. If you've marked where you stand, it's time to lift your gaze a little forward. Today, pick the next flag's place and take the first step toward it. The distance may be short, but a direction changes the walking.", "旗は、立てる瞬間より、次の場所を決める瞬間に力が生まれます。いま立っている場所に印をつけたなら、今度は視線を少し先へ移す番です。今日は次の旗の場所をひとつ決めて、そちらへ最初の一歩を運ぶ日。距離は短くても、向きが定まれば歩き方が変わります。", "旗的力量，不在插下的那一刻，在定下一处的那一刻。标记了脚下的位置，接下来把视线往前挪一点。今天定一个下一面旗的位置，朝它迈出头一步。距离短没关系，有了方向，步子就不一样。"],
            ["가끔은 뒤돌아서 지나온 깃발들을 세어보는 날이 필요해요. 얼마나 왔는지 돌아본 적이 한동안 없었을 거예요. 앞만 보면 제자리 같아도, 뒤를 보면 꽂아온 자리들이 줄지어 있어요. 오늘은 그 줄을 눈으로 따라가 보는 것으로 오늘 몫은 다한 거예요.", "Now and then you need a day to turn around and count the flags behind you. It's probably been a while since you looked at how far you've come. Facing only forward, it feels like standing still, but look back and the planted markers stand in a row. Following that line with your eyes is today's full share.", "ときには振り返って、立ててきた旗を数える日も必要です。どれだけ来たか、振り返ることがしばらくなかったはず。前だけ見ると足踏みのようでも、後ろを見れば、立ててきた場所が連なっています。今日はその連なりを目でたどるだけで、今日のぶんは果たしたことになります。", "偶尔需要回身数一数插过的旗。有多久没有回望来路了。只看前方像在原地，往后看，插下的位置排成了一列。今天用眼睛顺着那条线走一遍，今天的份就算尽到了。"],
            ["깃발은 정상에만 꽂는 게 아니에요. 중턱에 꽂는 깃발은 포기가 아니라 숨 고르기의 표시예요. 더 가야 한다는 마음이 요즘 어깨를 눌렀다면, 오늘은 여기까지라고 적어두고 앉아도 돼요. 쉼터에 꽂힌 깃발도 지도에는 똑같이 남아요.", "Flags aren't only for summits. A flag on the hillside isn't surrender. It's the mark of catching your breath. If the need to keep going has been pressing on your shoulders, today you can write that this is far enough and sit down. A flag planted at the resting spot stays on the map all the same.", "旗は頂にだけ立てるものではありません。中腹に立てる旗は、あきらめではなく息継ぎの印です。まだ先へ行かなければという気持ちが、この頃肩に載っていたなら、今日はここまでと書いて腰を下ろして大丈夫。休み場に立った旗も、地図には同じように残ります。", "旗不是只能插在山顶。插在半山腰的旗，不是放弃，是调息的记号。还得继续走的念头最近压着肩膀的话，今天写下到这里，坐下来也行。插在歇脚处的旗，在地图上留得一样清楚。"],
        ]),
        TarotCard(id: 33, name: ["오르막", "The Climb", "上り坂", "上坡路"], icon: "ArrowUp", readings: [
            ["다리에 힘이 붙은 게 느껴지는 날이에요. 버겁다고 느꼈던 요즘의 구간이 사실은 내리막이 아니라 오르막이었다는 뜻이기도 해요. 오늘은 가파른 구간을 몰아쳐 올라도 숨이 따라와요. 어디까지 오를지는 당신의 다리와 상의해서 정하세요.", "You can feel the strength in your legs today. The stretch that felt so heavy lately wasn't a downhill slide. It was a climb. Today, even pushing hard up the steep section, your breath keeps up. How high to go, settle that with your own two legs.", "脚に力がついてきたのを感じる日です。きつかったこの頃の区間は、下り坂ではなく上りの最中だったということでもあります。今日は急な区間をひと息に登っても、呼吸がついてきます。どこまで登るかは、あなたの脚と相談して決めてください。", "腿上有劲的日子。近来觉得吃力的这段，其实不是在走下坡，而是在爬坡。今天就算一鼓作气冲上陡的那段，呼吸也跟得上。爬到哪儿，和你的腿商量着定。"],
            ["오르막에서는 보폭을 넓히는 게 아니라 걸음 수를 늘리는 거예요. 크게 내딛으려다 멈추느니 작게 자주 딛는 쪽이 결국 위에 있어요. 숨이 차는 건 못 가고 있다는 신호가 아니라 올라가고 있다는 증거예요. 오늘은 작은 걸음으로 꾸준히 올라보세요.", "On a climb you don't lengthen your stride. You add steps. Small and frequent beats big and stalled, and it's the small steps that end up on top. Being winded isn't a sign you're falling short. It's proof you're gaining height. Today, keep climbing in small steps.", "上り坂では、歩幅を広げるのではなく、歩数を増やすのです。大きく踏み出して止まるより、小さく刻んで進むほうが、結局は上にいます。息が切れるのは進めていない印ではなく、登っている証拠。今日は小さな歩みで、こつこつ登ってみてください。", "上坡不是迈大步，是加步数。与其大跨一步就停，不如小步勤走，最后站在上面的是后者。喘，不是走不动的信号，是正在向上的证据。今天用小步，稳稳地爬。"],
            ["오르막 중턱에는 숨을 고르라고 있는 평평한 자리가 있어요. 오늘이 바로 그 자리예요. 잠시 뒤돌아보면 올라온 만큼의 경치가 이미 발아래 펼쳐져 있어요. 더 오르는 건 그 경치를 충분히 눈에 담은 다음이어도 늦지 않아요.", "Halfway up every climb there's a flat spot put there for catching breath. Today is that spot. Turn around for a moment and the view you've earned is already spread below. Climbing on can wait until you've taken it in fully. That won't be late.", "上り坂の中腹には、息を整えるための平らな場所があります。今日がちょうどその場所です。少し振り返れば、登ってきたぶんの景色がもう足もとに広がっています。さらに登るのは、その景色を十分に目へ収めてからでも遅くありません。", "上坡半途，有一块专为调息而设的平地。今天正是那块平地。回头看看，爬过的高度换来的景色已经铺在脚下。再往上，等把这片景色看够了也不迟。"],
            ["오르막에서는 짐을 줄이는 게 걸음을 살려요. 다 짊어지고 오르려던 요 며칠, 어깨가 먼저 알고 있었을 거예요. 오늘은 배낭에서 하나를 꺼내 길가에 내려두는 날이에요. 그 짐은 내려올 때 다시 챙겨도 되고, 안 챙겨도 돼요.", "On a climb, lightening the pack is what saves the legs. Your shoulders probably knew before you did, these past few days of hauling everything. Today, take one thing out of the bag and set it by the path. You can pick it up on the way down, or not.", "上り坂では、荷を減らすことが歩みを生かします。全部背負って登ろうとしていたこの頃、肩が先に知っていたはずです。今日はかばんからひとつ取り出して、道端に置いていく日。その荷は下りで拾ってもいいし、拾わなくてもいいのです。", "上坡路上，减负才保得住脚步。什么都背着往上走的这几天，肩膀早就知道了。今天从背包里取出一件，放在路边。那件行李，下山时再取也行，不取也行。"],
        ]),
        TarotCard(id: 34, name: ["징검다리", "The Stepping Stones", "飛び石", "踏脚石"], icon: "MoreHorizontal", readings: [
            ["돌 사이가 유난히 좁게 느껴지는 날이에요. 막막해 보이던 강도 오늘은 성큼성큼 건널 수 있을 것 같은 감각이 와요. 그 감각을 믿고 두세 칸을 이어 건너도 발이 미끄러지지 않는 흐름이에요. 건너편에 무엇이 기다리는지는 건넌 사람만 알게 돼요.", "The stones feel unusually close together today. Even the river that looked daunting seems crossable in strides, and that feeling can be trusted. The flow today keeps your feet from slipping even when you take the stones in pairs. What waits on the far bank, only the one who crosses finds out.", "石と石の間が、ふしぎと近く感じられる日です。渡れそうにないと見えた川も、今日はすいすい越えられそうな感覚がやってきます。その感覚を信じて、ふたつみっつ続けて渡っても、足がすべらない流れです。向こう岸に何が待っているかは、渡った人だけが知ることになります。", "石头间的距离显得格外近的日子。看着茫茫的河，今天也有大步跨过去的感觉。信着这份感觉连跨两三块，脚下也不打滑的势头。对岸有什么等着，只有过去的人知道。"],
            ["강 전체를 건널 방법은 몰라도 다음 돌 하나는 보여요. 큰일 앞에서 막막했던 마음, 사실은 전부를 한 번에 건너려 해서였을 거예요. 오늘은 다음 돌 하나에만 발을 올리는 날이에요. 디디고 나면 그다음 돌이 저절로 눈에 들어와요.", "You may not know how to cross the whole river, but the next stone shows. The dread in front of the big task probably came from trying to cross all of it at once. Today, put your foot on the next stone only. Once you're standing there, the one after shows itself.", "川全体を渡る方法はわからなくても、次の石ひとつなら見えています。大きなことを前に途方に暮れていたのは、実は全部をいちどに渡ろうとしていたから。今日は次の石ひとつにだけ、足を載せる日です。踏んでしまえば、その次の石はひとりでに目に入ってきます。", "过整条河的办法不知道，下一块石头却看得见。大事当前的茫然，多半是想一步跨完全程闹的。今天只把脚放上下一块石头。踩稳了，再下一块自然会跳进眼里。"],
            ["징검다리 앞에서는 물살을 먼저 읽는 사람이 젖지 않아요. 오늘은 건너기보다 디딜 돌을 고르는 날이에요. 어느 돌이 단단하고 어느 돌이 흔들리는지 강가에 서서 눈으로 짚어보세요. 미리 골라둔 돌은 내일의 발걸음을 기다려줘요.", "At the stepping stones, the one who reads the current first stays dry. Today is for choosing stones, not for crossing. From the bank, mark with your eyes which ones sit firm and which ones rock. Stones chosen ahead of time wait for tomorrow's footsteps.", "飛び石の前では、流れを先に読む人が濡れずにすみます。今日は渡るより、踏む石を選ぶ日です。どの石が固くて、どの石が揺れるのか、岸辺に立って目で確かめておいて。先に選んでおいた石は、明日の足取りを待っていてくれます。", "在踏脚石前，先读水势的人不湿鞋。今天不过河，挑要踩的石头。哪块稳，哪块晃，站在岸边用眼睛点一点。挑好的石头，会等着明天的脚。"],
            ["흔들리는 돌 위에서는 멈추는 게 기술이에요. 건너던 중에 잠시 서 있는 건 뒷걸음이 아니에요. 빨리 건너야 한다는 마음이 발끝을 재촉했다면, 오늘은 무릎을 살짝 굽히고 균형부터 잡는 날이에요. 물은 기다려주니 서두르는 마음만 내려놓으면 돼요.", "On a rocking stone, stopping is the skill. Standing still mid-crossing isn't a step backward. If the need to hurry across has been pushing at your toes, today bend your knees slightly and find your balance first. The water will wait. Only the rushing needs to be set down.", "揺れる石の上では、止まることが技術です。渡る途中で立ち止まるのは、後戻りではありません。早く渡らなければという気持ちがつま先を急かしていたなら、今日はひざを少しゆるめて、釣り合いを取ることから。川は待ってくれますから、急ぐ気持ちだけ下ろせばいいのです。", "在晃动的石头上，停住才是技术。过河途中站一会儿，不是退。要快点过去的念头催着脚尖的话，今天先屈一屈膝，把平衡找回来。水会等，放下急着走的心就行。"],
        ]),
        TarotCard(id: 35, name: ["표지판", "The Signpost", "道しるべ", "路标"], icon: "MapPin", readings: [
            ["표지판이 가리키는 방향과 걸어온 방향이 겹치는 날이에요. 잘 가고 있는 건지 몰라 뒤척였던 마음에, 오늘은 맞게 가고 있다는 확인이 도착해요. 확인이 됐으면 속도를 올려도 좋아요. 얼마나 힘차게 나아갈지는 당신 발에 달려 있어요.", "The direction the signpost points and the direction you've walked line up today. To the part of you that lay awake wondering if you were on track, confirmation arrives that you are. Once it's confirmed, you can pick up speed. How hard to stride is up to your feet.", "道しるべの指す方角と、歩いてきた方角が重なる日です。ちゃんと進めているのかわからず寝返りを打っていた心に、今日は合っているという確かめが届きます。確かめられたなら、速度を上げても大丈夫。どれほど力強く進むかは、あなたの足にかかっています。", "路标指的方向和走来的方向重合的日子。走得对不对，翻来覆去睡不安稳的心，今天收到了走对了的确认。确认过了，就可以提速。步子迈多大，由你的脚定。"],
            ["갈림길에서 오래 서 있으면 두 길 다 멀어져요. 어느 쪽이 정답인지 몰라 붙들고만 있던 선택이 하나 있었을 거예요. 오늘은 마음이 기우는 한쪽을 고르고 걸음을 떼보는 날이에요. 길은 걷기 시작한 사람에게만 다음 표지판을 보여줘요.", "Stand too long at a fork and both roads grow distant. There's probably one choice you've been holding, unsure which way is right. Today, pick the side your heart tilts toward and take a step. The road shows its next signpost only to the one who's walking.", "分かれ道に長く立っていると、どちらの道も遠ざかります。どちらが正解かわからず、抱えたままだった選択がひとつあったはず。今日は心の傾くほうを選んで、歩き出してみる日です。道は、歩き始めた人にだけ、次の道しるべを見せてくれます。", "在岔路口站得越久，两条路都在变远。哪边才对，攥着不放的选择，大概有一个。今天挑心偏向的那边，迈开步子。路，只把下一块路标指给开始走的人看。"],
            ["오늘은 지도를 펴고 현재 위치에 점을 찍는 날이에요. 어디로 갈지보다 어디에 서 있는지를 아는 게 먼저예요. 생각보다 멀리 와 있을 수도, 생각과 다른 길일 수도 있지만 어느 쪽이든 점을 찍어야 다음 선이 그어져요. 펜은 당신 손에 있어요.", "Today is for opening the map and marking where you are. Before where to go, knowing where you stand comes first. You may be farther along than you thought, or on a different road than you planned. Either way, only a marked point lets the next line be drawn. The pen is in your hand.", "今日は地図を広げて、いまいる場所に印をつける日です。どこへ行くかより、どこに立っているかを知るのが先。思ったより遠くまで来ているかもしれないし、思いと違う道かもしれませんが、どちらでも、点を打ってこそ次の線が引けます。ペンはあなたの手の中にあります。", "今天摊开地图，在现在的位置点一个点。去哪里之前，先知道站在哪里。也许比想的走得远，也许和想的不是一条路，但不论哪种，点下了点，才画得出下一条线。笔在你手里。"],
            ["표지판 앞에 서 있는 건 길을 잃은 게 아니에요. 어디로 갈지 정하지 못하는 자신이 답답했을지 몰라요. 하지만 멈춰 서서 표지판을 읽는 시간도 엄연히 여정의 일부예요. 오늘은 방향을 정하지 않고 그 자리에 서 있어도 괜찮아요.", "Standing at a signpost isn't being lost. You may have felt frustrated with yourself for not choosing a direction. But the time spent stopped, reading the signs, is fully part of the journey. Today you're allowed to stand right there without picking a way.", "道しるべの前に立っているのは、道に迷ったのとは違います。行き先を決められない自分がもどかしかったかもしれません。けれど立ち止まって道しるべを読む時間も、まぎれもなく旅路の一部です。今日は方角を決めずに、その場所に立っていても大丈夫です。", "站在路标前，不等于迷了路。定不下往哪儿走的自己，也许让你烦闷。可停下来读路标的时间，也是旅程实实在在的一部分。今天不定方向，就站在原地，也可以。"],
        ]),
        TarotCard(id: 36, name: ["지구본", "The Globe", "地球儀", "地球仪"], icon: "Globe", readings: [
            ["지구본을 돌리다 낯선 곳에 손끝이 멎는 날이에요. 익숙한 동네만 맴돌던 시야가 오늘은 한 뼘 바깥까지 궁금해져요. 안 해본 것, 안 가본 영역에 발을 딛어도 좋은 흐름이에요. 어디에 손끝을 멈출지는 당신의 호기심이 정해줄 거예요.", "A day when your fingertip stops on an unfamiliar place as the globe spins. Sight that circled the same neighborhood grows curious about the world one span out. The current favors stepping into what you haven't tried, haven't visited. Where the finger lands, your curiosity will decide.", "地球儀を回していて、見知らぬ場所で指先が止まる日です。なじみの町ばかり巡っていた視野が、今日はひと回り外まで気になってきます。やったことのないこと、踏み入れたことのない領域に足を置いてもいい流れです。どこで指を止めるかは、あなたの好奇心が決めてくれます。", "转着地球仪，指尖停在陌生地方的日子。只在熟悉的街区打转的视野，今天对一拃开外也好奇起来。没做过的事、没踏过的领域，正是可以落脚的势头。指尖停在哪里，交给你的好奇心。"],
            ["세상 전부를 도는 여행이 아니어도 시야는 넓어져요. 오늘은 늘 보던 범위 바깥에서 동네 하나를 골라 들여다보는 날이에요. 낯선 분야의 글 한 편, 안 듣던 음악 한 곡이면 충분해요. 새로 안 것 하나가 익숙한 자리의 공기까지 바꿔요.", "The view widens without a trip around the world. Today, pick one neighborhood outside your usual range and look in. One article from a strange field, one song you'd never queue is enough. One new thing learned changes the air of the familiar places too.", "世界をぜんぶ回る旅でなくても、視野は広がります。今日はいつも見ている範囲の外から、町をひとつ選んでのぞいてみる日。なじみのない分野の文章ひとつ、聴いたことのない曲ひとつで十分です。新しく知ったひとつが、なじんだ場所の空気まで変えてくれます。", "不必环游世界，视野也能变宽。今天从常看的范围外面，挑一个街区看看。陌生领域的一篇文章、没听过的一首歌，足够了。新知道的一样东西，连熟悉位置的空气也会换掉。"],
            ["지구본은 너무 빨리 돌리면 나라의 색이 다 뭉개져요. 오늘은 천천히 돌리며 넓게 조망하는 날이에요. 코앞의 일에 파묻혀 좁아졌던 시야를 한 바퀴 돌려 펴는 것만으로 숨통이 트여요. 멀리서 보면 지금 고민의 크기도 달리 보여요.", "Spin a globe too fast and the countries smear together. Today, turn it slowly and take the wide view. Just unfolding the sight that had narrowed around what's in front of you lets the breath back in. From far enough away, even today's worry changes size.", "地球儀は、速く回しすぎると国の色がにじんでしまいます。今日はゆっくり回して、広く見渡す日です。目先のことに埋もれて狭くなっていた視野を、ひと回りひらくだけで息がとおります。遠くから見れば、いまの悩みの大きさも違って見えてきます。", "地球仪转太快，国家的颜色会糊成一片。今天慢慢转，看个大概。被眼前的事埋住而变窄的视野，转开一圈，气就顺了。隔远一看，眼下烦恼的个头也不一样了。"],
            ["세상이 넓다는 게 다 가봐야 한다는 뜻은 아니에요. 남들이 딛는 곳들을 보며 마음이 조급해졌던 요즘이었을지 몰라요. 오늘은 지구본을 돌리는 손을 멈추고 내 자리의 좌표를 아껴주는 날이에요. 여기도 지도 위의 어엿한 한 점이에요.", "A wide world doesn't mean you owe it a visit everywhere. Watching where everyone else sets foot may have made you restless lately. Today, still the spinning hand and be kind to your own coordinates. This spot is a full point on the map too.", "世界が広いことは、すべて行かなければならないという意味ではありません。人の踏む場所を眺めて、気が急いていた日々だったかもしれません。今日は地球儀を回す手を止めて、自分の場所の座標をいとおしむ日です。ここも、地図の上のれっきとしたひと粒の点なのです。", "世界很大，不等于都得去过。看着别人的落脚处而心急的近来，也许有过。今天停下转动地球仪的手，疼惜自己所在的坐标。这里，也是地图上实实在在的一点。"],
        ]),
        TarotCard(id: 37, name: ["소나무", "The Pine Tree", "松の木", "松树"], icon: "TreePine", readings: [
            ["뿌리 깊은 나무는 드리우는 그늘도 넓은 법이에요. 흔들리지 않으려 버텨온 시간이 오늘은 남을 쉬게 하는 힘이 돼요. 곁의 누군가에게 그늘 한 자리를 내어줘도 뿌리는 끄떡없어요. 누구를 그 아래로 부를지는 당신 마음이에요.", "A deep-rooted tree casts a wide shade. The time you've spent holding steady becomes, today, the strength that lets someone else rest. Offer a seat in your shade and the roots won't so much as shiver. Who to invite under the branches is up to you.", "根の深い木は、落とす木陰も広いものです。揺れまいと踏ん張ってきた時間が、今日は人を休ませる力になります。そばの誰かに木陰をひと席分けてあげても、根はびくともしません。誰をその下へ招くかは、あなたの心しだいです。", "根深的树，投下的荫凉也宽。为了不晃而撑住的时间，今天成了让别人歇脚的力气。给身边的谁让出一片树荫，根也纹丝不动。请谁到树下来，随你的心。"],
            ["소나무는 계절이 바뀌어도 하던 대로 푸르러요. 새로운 것에 눈이 가는 날일수록, 늘 하던 것을 묵묵히 이어가는 사람이 끝내 멀리 가요. 지켜온 습관 하나를 오늘도 거르지 않는 것, 그게 오늘의 전진이에요. 반복은 당신 편이에요.", "The pine stays green the way it always has, whatever the season does. On days when the new and shiny pulls at the eye, it's the one who quietly keeps doing the usual thing who ends up farthest along. Not skipping the one habit you've kept, that's today's advance. Repetition is on your side.", "松は季節が変わっても、いつものように青いままです。新しいものに目が向く日ほど、いつものことを黙々と続ける人が、最後には遠くへ行きます。守ってきた習慣ひとつを今日も欠かさないこと、それが今日の前進です。繰り返しは、あなたの味方です。", "松树换了季节，也照旧青着。越是新鲜事勾眼睛的日子，把惯常的事闷头续上的人，走得越远。守了很久的那个习惯，今天也不落下，这就是今天的前进。重复站在你这边。"],
            ["바람 부는 날의 소나무는 흔들리되 부러지지 않아요. 주변이 빠르게 변해서 마음이 일렁였던 요즘이었을 거예요. 흔들리는 것과 뿌리가 뽑히는 건 전혀 다른 일이에요. 오늘은 흔들리는 가지 말고 박혀 있는 뿌리 쪽을 믿어보세요.", "A pine in the wind sways and doesn't break. With everything changing fast around you, your footing probably wobbled a little lately. Swaying and being uprooted are entirely different things. Today, trust the root that's planted, not the branch that's moving.", "風の日の松は、揺れても折れません。まわりの変化が速くて、心が波立っていた日々だったはず。揺れることと、根が抜けることはまったく別のことです。今日は揺れる枝ではなく、土に張った根のほうを信じてみてください。", "起风的日子，松树摇而不折。近来周围变得快，心大概也跟着晃过。摇晃和连根拔起，完全是两回事。今天别看摇着的枝，去信扎着的根。"],
            ["늘푸름을 증명하려 애쓰는 나무는 없어요. 잘 버티고 있다는 걸 보여줘야 한다는 마음이 요즘 어깨에 얹혀 있었을지 몰라요. 오늘은 아무것도 증명하지 않고 그냥 서 있어도 되는 날이에요. 서 있는 것만으로 이미 소나무는 소나무예요.", "No tree strains to prove it's evergreen. The need to show you're holding up may have settled on your shoulders lately. Today you can stand there proving nothing. Standing is already the whole job. A pine is a pine just by being one.", "常緑を証明しようと励む木はありません。ちゃんと持ちこたえていると見せなければ、という気持ちが、この頃肩に載っていたかもしれません。今日は何も証明せず、ただ立っているだけでいい日です。立っているだけで、松はもう松なのです。", "没有一棵树会努力证明自己常青。得让人看见自己撑得住，这个念头最近也许压在肩上。今天什么也不证明，就那么站着也行。光是站着，松树就已经是松树了。"],
        ]),
        TarotCard(id: 38, name: ["쪽지", "The Note", "小さなメモ", "小纸条"], icon: "MessageText", readings: [
            ["짧은 한마디가 유난히 크게 닿는 날이에요. 길게 설명하려다 결국 삼킨 말이 하나쯤 있었을 거예요. 오늘은 아껴둔 그 말을 건네도 좋은 날이라, 다듬다 만 문장이어도 진심이면 충분히 도착해요. 받을 사람의 얼굴은 이미 떠올라 있을 거예요.", "A short line lands unusually deep today. There's probably a thing you meant to explain at length and ended up swallowing. Today you can hand over the words you've been saving, and even an unfinished sentence arrives whole if it's honest. The face of the person receiving it has already come to mind.", "短いひと言が、ひときわ深く届く日です。長く説明しようとして、結局のみ込んだ言葉がひとつくらいあったはず。今日はとっておいたその言葉を手渡してもいい日で、磨きかけの文でも、真心ならちゃんと届きます。受け取る人の顔は、もう浮かんでいるのではないでしょうか。", "短短一句话传得格外远的日子。想解释周全，最后咽回去的话，大概有一句。今天可以把攒着的那句递出去，就算是没磨完的句子，只要是真心，足以抵达。收的人的脸，已经浮现了吧。"],
            ["긴 편지를 쓰려다 한 줄도 못 쓰는 것보다 쪽지 한 장이 나아요. 고맙다든가 생각난다든가, 짧은 진심 한 줄이면 돼요. 오늘은 길어지는 고민을 줄이고 먼저 전하는 날이에요. 접힌 쪽지는 손에서 손으로 건네지는 순간에만 펴져요.", "Better one note than a long letter never written. Thank you, or thinking of you, one short honest line will do. Today, cut the lengthening deliberation and send first. A folded note only opens in the moment it passes from hand to hand.", "長い手紙を書こうとしてひと行も書けないより、メモひと枚のほうがましです。ありがとうとか、ふと思い出したとか、短い本音のひと行で足ります。今日は長引く迷いを切り上げて、先に伝える日です。折りたたんだメモは、手から手へ渡る瞬間にだけひらかれます。", "与其想写长信一行也没动，不如一张纸条。谢谢，或者想起你了，一行短短的真心就够。今天缩短越拖越长的犹豫，先递出去。折起的纸条，只在手递到手的那一刻展开。"],
            ["말을 고르는 시간도 대화의 일부예요. 바로 답하지 못했다고 마음이 없는 게 아니라는 걸 당신은 알고 있어요. 오늘은 쓸 말을 천천히 고르며 상대의 말을 한 번 더 읽어보는 날이에요. 천천히 고른 만큼 말은 정확하고 다정해져요.", "Choosing your words is part of the conversation too. Not answering right away doesn't mean the feeling isn't there, and you know that. Today, pick your words slowly and read the other person's once more. Words chosen slowly come out precise and kind.", "言葉を選ぶ時間も、会話の一部です。すぐに返せなかったからといって、気持ちがないわけではないことを、あなたは知っています。今日は書く言葉をゆっくり選びながら、相手の言葉をもう一度読み返す日。ゆっくり選んだぶんだけ、言葉は正確で、やさしくなります。", "斟酌词句的时间，也是对话的一部分。没能马上回复，不等于没有心意，这一点你是懂的。今天慢慢挑要写的话，把对方的话再读一遍。挑得慢，话就准，也更温柔。"],
            ["쪽지는 접어서 주머니에 가만히 넣어두는 날도 있는 법이에요. 해야 할 말이 목까지 차올랐어도 오늘은 무게를 덜어내는 쪽이에요. 하룻밤 주머니에서 익은 말은 더 부드러워져요. 그 쪽지를 꺼낼 때를 정하는 건 언제나 당신이에요.", "Some days the note stays folded in your pocket. Even with words risen to your throat, today leans toward setting weight down. A line that rests overnight in the pocket softens. When to take the note out is always yours to decide.", "メモを折りたたんで、ポケットにしまっておく日もあるものです。言うべきことが喉元までせり上がっていても、今日は重みを減らす側です。ひと晩ポケットで熟した言葉は、いっそう柔らかくなります。そのメモを取り出すときを決めるのは、いつだってあなたです。", "也有把纸条折好、静静放进口袋的日子。就算要说的话涌到喉咙口，今天也选卸下分量的那边。在口袋里焐过一夜的话，会更软和。什么时候掏出那张纸条，从来都由你定。"],
        ]),
        TarotCard(id: 39, name: ["되감기", "The Rewind", "巻き戻し", "倒带"], icon: "Undo", readings: [
            ["다시 들어도 좋은 소절이 많은 테이프가 있어요. 지나온 장면들 속에 이미 배워둔 것이 생각보다 많다는 뜻이에요. 오늘은 그때 익힌 방식을 꺼내 크게 써먹어도 되는 날이에요. 어느 소절을 오늘에 겹쳐볼지, 손잡이는 당신에게 있어요.", "Some tapes are full of passages worth hearing again. It means the scenes you've lived already hold more learning than you thought. Today you can pull out a method you once picked up and use it at full size. Which passage to lay over today, the handle is in your hand.", "もう一度聴いてもいい節の多いテープがあります。過ぎてきた場面の中に、すでに学び取ったものが思いのほか多いということです。今日はあのとき身につけたやり方を取り出して、思いきり使ってもいい日。どの節を今日に重ねるか、つまみはあなたの手にあります。", "有一盘磁带，哪一段重听都好。这说明走过的画面里，早已学会的东西比想象中多。今天可以把当年练熟的法子拿出来，放开了用。把哪一段叠在今天上面，旋钮在你手里。"],
            ["복기는 한 장면이면 족해요. 마음에 걸린 채 지나간 장면 하나가 요즘 이따금 떠올랐을 거예요. 오늘은 그 장면만 천천히 되감아 배울 것 하나를 꺼내고, 바로 다음 재생으로 넘어가는 날이에요. 테이프는 앞으로 감길 때 노래가 돼요.", "One scene is enough to review. A moment that passed while snagging on your mind has probably resurfaced now and then. Today, rewind just that scene slowly, take out one lesson, and roll straight into the next play. A tape only becomes a song winding forward.", "振り返りは、ひとつの場面で足ります。心に引っかかったまま過ぎた場面が、この頃ときどき浮かんでいたはず。今日はその場面だけゆっくり巻き戻して、学べることをひとつ取り出したら、すぐ次の再生へ進む日です。テープは、前へ回るときに歌になります。", "复盘，一个画面就够。带着心结翻篇的那个场面，最近偶尔会浮上来吧。今天只把那一段慢慢倒回去，取出一样可学的，马上切回播放。磁带向前走的时候，才成为歌。"],
            ["테이프를 천천히 돌리면 빠르게 들을 땐 놓쳤던 소리가 들려요. 오늘은 흘러온 흐름을 낮은 속도로 확인하는 날이에요. 잘한 것과 아쉬운 것을 판정하려는 게 아니라 그냥 다시 들어보는 거예요. 들리는 만큼만 알아두면 돼요.", "Play the tape slowly and sounds appear that speed ran past. Today is for checking the flow at low speed. Not to rule on what went well or poorly, just to listen once more. Take in only as much as you can hear. That's enough.", "テープをゆっくり回すと、速く聴いていたときには逃していた音が聞こえます。今日は流れてきたものを、低い速さで確かめる日。うまくいったか、悔いが残るかを判定するのではなく、ただもう一度聴いてみるだけです。聞こえたぶんだけ、覚えておけばいいのです。", "磁带慢速转，会听见快听时漏掉的声音。今天用低速把这一路的流向确认一遍。不是要判定哪里好哪里糟，只是再听一遍。听见多少，记下多少就好。"],
            ["같은 소절을 자꾸 되감으면 테이프도 마음도 함께 늘어나요. 그 장면을 이미 여러 번 재생해봤다는 걸 당신도 알 거예요. 오늘은 되감기 버튼에서 슬며시 손을 떼어보는 날이에요. 늘어난 마음은 앞으로 감아야 다시 팽팽해져요.", "Rewind the same passage too many times and both tape and heart stretch thin. You know you've replayed that scene plenty already. Today, ease your hand off the rewind button. A stretched heart tightens back up only by winding forward.", "同じ節を何度も巻き戻すと、テープも心も一緒に伸びてしまいます。あの場面をもう何度も再生してきたことは、あなた自身が知っているはず。今日は巻き戻しのボタンから、そっと指を離してみる日です。伸びた心は、前へ回してこそ、また張りを取り戻します。", "同一段反复倒带，磁带和心都会被拉松。那个画面你已经放过很多遍，这一点你自己也知道。今天试着把手从倒带键上轻轻挪开。松掉的心，向前走带才会重新绷紧。"],
        ]),
    ]

    private static func langIndex(_ lang: String) -> Int {
        switch lang {
        case "en": return 1
        case "ja": return 2
        case "zh": return 3
        default:   return 0
        }
    }

    private static func tierIndex(_ tier: AuraTier) -> Int {
        switch tier {
        case .great: return 0
        case .good:  return 1
        case .fair:  return 2
        case .care:  return 3
        }
    }

    /// 카드 이름(현재 언어).
    static func name(_ card: TarotCard, lang: String) -> String {
        guard card.name.count >= 4 else { return "" }
        return card.name[langIndex(lang)]
    }

    /// 그날 그 기운의 등급에 맞는 해설(현재 언어). 화면은 이 한 곳만 읽는다.
    static func reading(_ card: TarotCard, tier: AuraTier, lang: String) -> String {
        let t = tierIndex(tier)
        guard card.readings.count > t, card.readings[t].count >= 4 else { return "" }
        return card.readings[t][langIndex(lang)]
    }

    /// 저장된 cardId 를 관용적으로 해석 — 0..39 정수만 인정.
    static func card(forId id: Int) -> TarotCard? {
        guard deck.indices.contains(id) else { return nil }
        return deck[id]
    }
}
